def _is_abort(line, homing_name):
    """True if `line` is a stop aimed at the axis currently homing (or a global STOP/BYE)."""
    parts = line.split()
    if not parts:
        return False
    c = parts[0].upper()
    if c == "BYE":
        return True
    rest = parts[1:]
    if rest and rest[0].upper() in ("Y", "Z"):
        name = rest[0].lower()
        rest = rest[1:]
    else:
        name = "y"
    if c == "STOP":
        return name == homing_name
    if c == "EN":
        return name == homing_name and bool(rest) and rest[0] == "0"
    return False

def _parse_rx_sweep(spec: str) -> list[float]:
    """Parse 'lo:hi:N' into N evenly spaced rx targets, inclusive of both ends."""
    try:
        lo_s, hi_s, n_s = spec.split(":")
        lo, hi, n = float(lo_s), float(hi_s), int(n_s)
    except ValueError as exc:
        raise ValueError(f"--rx-sweep must be lo:hi:N (rad:rad:count), got {spec!r}") from exc
    if n < 2:
        raise ValueError("--rx-sweep needs N >= 2 sample points")
    if hi <= lo:
        raise ValueError("--rx-sweep needs hi > lo")
    return [lo + i * (hi - lo) / (n - 1) for i in range(n)]

def _parse_pos(reply):
    """Parse 'OK POS [axis] <mm> <homed> <moving>' -> (mm, homed, moving)."""
    f = reply.split()
    i = 2
    if i < len(f) and f[i].upper() in ("Y", "Z"):
        i += 1
    return float(f[i]), bool(int(f[i + 1])), bool(int(f[i + 2]))

