from typing import Any


def _upstream_error_details(body: Any) -> tuple[str, str | None]:
    """Extract (message, code) from an upstream error body.

    Handles two shapes: the OpenAI/vLLM nested ``{"error": {...}}`` envelope
    and SGLang's flat ``{"object": "error", "message": ..., "code": ...}``
    body (no ``error`` wrapper, integer ``code``).
    """
    if not isinstance(body, dict):
        return "", None
    error = body.get("error")
    if isinstance(error, dict):
        message = error.get("message")
        code = error.get("code")
        return (
            message if isinstance(message, str) else "",
            code if isinstance(code, str) else None,
        )
    if isinstance(error, str):
        return error, None
    # SGLang flat shape: top-level message/code with no "error" envelope.
    if "message" in body:
        message = body.get("message")
        code = body.get("code")
        return (
            message if isinstance(message, str) else "",
            code if isinstance(code, str) else None,
        )
    return "", None

from typing import Any


def _flatten_input_content(content: Any) -> str:
    """Flatten text input blocks and reject unsupported multimodal blocks."""
    if content is None or isinstance(content, str):
        return content or ""
    if isinstance(content, list):
        parts = []
        for part in content:
            if not isinstance(part, dict):
                parts.append(str(part))
                continue
            part_type = part.get("type")
            if part_type not in (None, "text", "input_text", "output_text"):
                raise ValueError(
                    f"unsupported Responses content block type: {part_type!r}")
            parts.append(str(part.get("text") or ""))
        return "".join(parts)
    raise ValueError(
        f"unsupported Responses content value: {type(content).__name__}")

