def _from_dict(cls, d: dict):
    """From dict."""
    if d is None:
        return cls()
    valid_keys = {f.name for f in fields(cls)}
    filtered = {}
    for k, v in d.items():
        if k not in valid_keys:
            continue

        if isinstance(v, str):
            raw_value = v
            try:
                numeric_value = float(raw_value)
                if (
                    numeric_value.is_integer()
                    and "." not in raw_value
                    and "e" not in raw_value.lower()
                ):
                    v = int(numeric_value)
                else:
                    v = numeric_value
            except (ValueError, OverflowError):
                pass
        filtered[k] = v
    return cls(**filtered)

def split_range_for_rank(total: int, world_size: int, rank: int) -> tuple[int, int]:
    """Split range for rank."""
    if total % world_size != 0:
        raise ValueError(
            f"Dimension {total} is not divisible by world_size={world_size}; "
            "the current implementation requires even partitioning"
        )
    shard = total // world_size
    start = rank * shard
    return start, start + shard

