def extract_code_block(text: str) -> Optional[str]:
    """Extract code block."""
    if "```python" in text:
        code = text.split("```python")[-1].split("```")[0]
        return code.strip()
    elif "```" in text:
        parts = text.split("```")
        if len(parts) >= 3:
            code = parts[1]
            if "\n" in code:
                first_line, rest = code.split("\n", 1)
                if first_line.strip().isalpha():
                    return rest.strip()
            return code.strip()
    return None

