def _positive_float(value: Any) -> float | None:
    """Return a finite number strictly greater than zero, else ``None``."""
    if isinstance(value, bool) or value is None:
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    if parsed <= 0 or parsed != parsed or parsed == float("inf"):
        return None
    return parsed

import json


def _notebook_to_markdown(text: str) -> str:
    """Convert a Jupyter .ipynb (JSON) into readable markdown: markdown cells
    verbatim, code cells as fenced blocks, text outputs as plain output blocks.
    Falls back to the raw text if it is not valid notebook JSON."""
    try:
        nb = json.loads(text)
        cells = nb["cells"]
    except Exception:
        return text
    lang = "python"
    try:
        meta = nb.get("metadata", {})
        lang = (meta.get("kernelspec", {}).get("language")
                or meta.get("language_info", {}).get("name") or "python")
    except Exception:
        pass

    def _src(cell):
        s = cell.get("source", "")
        return "".join(s) if isinstance(s, list) else (s or "")

    out = []
    for cell in cells:
        ct = cell.get("cell_type")
        if ct in ("markdown", "raw"):
            chunk = _src(cell).strip()
            if chunk:
                out.append(chunk)
        elif ct == "code":
            code = _src(cell).rstrip()
            if code:
                out.append(f"```{lang}\n{code}\n```")
            for o in cell.get("outputs", []):
                txt = ""
                if o.get("output_type") == "stream":
                    t = o.get("text", "")
                    txt = "".join(t) if isinstance(t, list) else t
                elif o.get("output_type") in ("execute_result", "display_data"):
                    d = (o.get("data") or {}).get("text/plain", "")
                    txt = "".join(d) if isinstance(d, list) else d
                txt = (txt or "").rstrip()
                if txt:
                    out.append("```\n" + txt[:2000] + "\n```")
    return "\n\n".join(out)

def parse_frontmatter(text: str) -> str:
    """Return only the frontmatter; full YAML parsing is unnecessary for these invariants."""
    if not text.startswith("---\n"):
        return ""
    end = text.find("\n---\n", 4)
    return "" if end < 0 else text[4:end]

import copy


def merge(base: object, patch: object) -> object:
    """Recursively merge fixture patches; one-item integration lists patch by index."""
    if isinstance(base, dict) and isinstance(patch, dict):
        result = copy.deepcopy(base)
        for key, value in patch.items():
            result[key] = merge(result[key], value) if key in result else copy.deepcopy(value)
        return result
    if isinstance(base, list) and isinstance(patch, list) and len(base) == len(patch) == 1:
        return [merge(base[0], patch[0])]
    return copy.deepcopy(patch)

from typing import TYPE_CHECKING, Any


def _extract_completion_text(raw: dict[str, Any]) -> str:
    """Extract the assistant completion text from an OpenAI-format response."""
    # OpenAI chat completion response format
    choices = raw.get("choices", [])
    if choices and isinstance(choices, list):
        first = choices[0]
        if isinstance(first, dict):
            msg = first.get("message", {})
            if isinstance(msg, dict):
                content = msg.get("content", "")
                if isinstance(content, str):
                    return content
            # text completion style
            text = first.get("text", "")
            if isinstance(text, str):
                return text
    return ""

from decimal import ROUND_DOWN, ROUND_HALF_UP, Decimal


def compute_saving_pct(current: Decimal, projected: Decimal) -> Decimal | None:
    """Compute (current - projected) / current as a percentage.

    Returns None when current is zero (no priced calls) to avoid
    ZeroDivisionError or NaN in reports (P3-4 fix).
    """
    if current == Decimal("0"):
        return None
    return ((current - projected) / current) * Decimal("100")

def _levenshtein(a: str, b: str) -> int:
    """Edit distance between two strings (no third-party dependency)."""
    if a == b:
        return 0
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

def _response_error_code(exc: Exception) -> str | None:
    """Extract a provider error ``code`` / ``type`` from a LiteLLM response."""
    response = getattr(exc, "response", None)
    if response is None:
        return None
    try:
        json_fn = getattr(response, "json", None)
        data = json_fn() if callable(json_fn) else None
    except (ValueError, TypeError, AttributeError):
        # Unparseable / absent body — fall back to the message heuristic.
        return None
    if not isinstance(data, dict):
        return None
    err = data.get("error", data)
    if not isinstance(err, dict):
        return None
    for key in ("code", "type"):
        value = err.get(key)
        if value:
            return str(value).lower()
    return None

import json


def parse_cdp_connect_headers(raw_headers: str) -> dict[str, str] | None:
    """Parse optional CDP headers without ever including their values in errors."""
    if not raw_headers.strip():
        return None
    try:
        payload = json.loads(raw_headers)
    except json.JSONDecodeError:
        raise ValueError("CDP_CONNECT_HEADERS must be valid JSON") from None
    if not isinstance(payload, dict) or not all(
        isinstance(name, str)
        and bool(name.strip())
        and isinstance(value, str)
        for name, value in payload.items()
    ):
        raise ValueError("CDP_CONNECT_HEADERS must be a JSON object of string headers")
    return payload

from typing import Any


def mark_equivalent_work(records: list[dict[str, Any]]) -> None:
    """Mark per-rep cross-backend step-count mismatches as soft failures."""
    groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for record in records:
        if record["category"] in ("navigation", "download"):
            groups.setdefault((record["case"], record["rep"]), []).append(record)

    for group in groups.values():
        comparable = [
            record for record in group if record.get("steps_completed") is not None
        ]
        if len({record["backend"] for record in comparable}) < 2:
            continue
        completed_counts = {record["steps_completed"] for record in comparable}
        equivalent = len(completed_counts) == 1
        for record in comparable:
            record["equivalent_work"] = equivalent
            if not equivalent:
                record["soft_fail"] = True
                record["soft_fail_reason"] = (
                    "backends completed different step counts for this case/rep"
                )

