import re


def snake_name(name: str) -> str:
    """Return a stable comparison key for Python and camelCase spellings."""
    first = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", name.replace("-", "_"))
    return re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", first).lower()

