import re


def safe_ai_failure_category(code: str, details: dict[str, Any] | None = None) -> str:
    """Collapse implementation errors into stable, non-private UI categories."""

    details = details or {}
    explicit = details.get("failure_category")
    if isinstance(explicit, str) and re.fullmatch(r"[A-Z][A-Z0-9_]{2,80}", explicit):
        return explicit
    if code in {"AI_ENGINE_UNAVAILABLE", "AI_AGENT_UNAVAILABLE", "AI_ENGINE_FAILED"}:
        return "AI_TRANSPORT_OR_RUNTIME"
    if code in {"AI_RESPONSE_INVALID", "AI_RESPONSE_REPAIR_FAILED"}:
        return "STRUCTURED_OUTPUT_CONTRACT"
    return "UNKNOWN_AI_FAILURE"

def parse_protocol_table(text: str) -> dict[str, dict[str, int]]:
    """Parse paired-header tables used by /proc/net/snmp and netstat."""
    result: dict[str, dict[str, int]] = {}
    lines = [line.split() for line in text.splitlines() if line.strip()]
    if not lines or len(lines) % 2:
        raise ValueError("malformed protocol table")
    index = 0
    while index + 1 < len(lines):
        header = lines[index]
        values = lines[index + 1]
        index += 2
        if not header or not values or header[0] != values[0]:
            raise ValueError("protocol header/value mismatch")
        protocol = header[0].rstrip(":")
        names = header[1:]
        raw_values = values[1:]
        if len(names) != len(raw_values):
            raise ValueError("protocol counter length mismatch")
        try:
            parsed = {name: int(value) for name, value in zip(names, raw_values)}
        except ValueError as exc:
            raise ValueError("invalid protocol counter") from exc
        result[protocol] = parsed
    return result

