import re


def _letters_in_range(spec):
    """'a-r' / 'a-r, plus h2 - NINETEEN checks' -> the set of letters the header claims."""
    m = re.search(r"([a-z])\s*[-–—]\s*([a-z])", spec)
    if not m:
        return None
    lo, hi = m.group(1), m.group(2)
    if lo > hi:
        return None
    return {chr(c) for c in range(ord(lo), ord(hi) + 1)}

import re


def picked(gates, directions):
    """Which of the rendered directions was chosen, from the recorded `direction_gate` line."""
    line = ""
    d = (gates or {}).get("design_plan")
    if isinstance(d, dict):
        line = str(d.get("direction_gate") or "")
        if isinstance(d.get("direction_pick"), str) and d["direction_pick"].strip():
            line = d["direction_pick"]
    if not line.strip():
        return None, "no `direction_gate` line to read the pick from"
    names = [str(x.get("name") or "") for x in directions if str(x.get("name") or "").strip()]

    # 🔴 Read the pick by finding a NAME in the line, not by parsing English prose. The checkpoint
    # convention says these lines follow the CONVERSATION language, so a Chinese deck writes
    # `方向闸门:选定 B — Aperture`, and a regex anchored on "picked ... of" reported NOT CHECKED for
    # every one of them — a check that fires only for the authors already writing in English is the
    # layering failure this repo keeps re-learning, one file over.
    hits = sorted(((line.lower().find(nm.lower()), nm) for nm in names
                   if nm.lower() in line.lower()), key=lambda t: t[0])
    if not hits:
        # No full name — fall back to a leading token ("picked B", "选定 B"), matched at a word
        # boundary so `B` never resolves to `B2`.
        for nm in sorted(names, key=len, reverse=True):
            head = re.split(r"\s*[—\-·:]\s*", nm)[0].strip()
            if head and re.search(r"(?<![\w])" + re.escape(head) + r"(?![\w])", line, re.I):
                return nm, None
        return None, "the `direction_gate` line names none of {}".format(names)
    if len(hits) == 1:
        return hits[0][1], None
    # Several names on one line is the NORMAL shape - the convention asks for the losers too. The
    # pick is the one a pick-marker introduces, in whatever language the line is written in.
    for m in re.finditer(r"(picked|chose|chosen|selected|selects?|选定|选择|选中|选了|采用|採用|選定)",
                         line, re.I):
        after = [(i, nm) for i, nm in hits if i >= m.end()]
        if after:
            return min(after, key=lambda t: t[0])[1], None
    return hits[0][1], None

def _band(rgb):
    """dark / mid / light — the coarse value a viewer registers before any hue."""
    v = sum(rgb) / 3.0
    return "dark" if v < 90 else ("light" if v > 200 else "mid")

def _runs(shape):
    """[(text, pt)] per non-empty paragraph — pt is None where no explicit size is set."""
    out = []
    if not getattr(shape, "has_text_frame", False):
        return out
    for para in shape.text_frame.paragraphs:
        txt = "".join(r.text or "" for r in para.runs) or (para.text or "")
        if not txt.strip():
            continue
        sizes = [r.font.size.pt for r in para.runs if r.font.size is not None]
        if not sizes and para.font.size is not None:
            sizes = [para.font.size.pt]
        out.append((txt.strip(), max(sizes) if sizes else None))
    return out

from collections import deque


def _bfs_distances(open_mask, start):
    """4-connected BFS shortest-path block distances from ``start`` cell.

    Returns dict {(r, c): dist} over all cells reachable from start.
    """
    rows, cols = open_mask.shape
    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and open_mask[nr, nc]:
                if (nr, nc) not in dist:
                    dist[(nr, nc)] = dist[(r, c)] + 1
                    queue.append((nr, nc))
    return dist

def auto_detect_entity_col(ws) -> int | None:
    """Pick the column with most non-numeric unique values as the entity column."""
    best_col, best_unique = None, 0
    n_rows = ws.max_row - 1
    if n_rows < 5:
        return None
    for c in range(1, ws.max_column + 1):
        non_num = []
        for r in range(2, ws.max_row + 1):
            v = ws.cell(r, c).value
            if isinstance(v, str) and v.strip():
                non_num.append(v)
        if len(non_num) < n_rows * 0.5:
            continue
        u = len(set(non_num))
        if u > best_unique:
            best_unique, best_col = u, c
    return best_col

import re


def tokens(text: str) -> set[str]:
    """Return entity-matching tokens: lowercased Latin words (≥3 chars) + Chinese 2-8 char runs."""
    out = set()
    for w in re.findall(r"[A-Za-z][A-Za-z\-]{2,}", text):
        out.add(w.lower())
    for w in re.findall(r"[\u4e00-\u9fff]{2,8}", text):
        out.add(w)
    return out

def entity_overlap(a: set, b: set) -> float:
    """Overlap as |a ∩ b| / max(|a|, |b|). 1.0 = identical entity sets."""
    if not a or not b:
        return 0.0
    return len(a & b) / max(len(a), len(b))

def resolve_compressed_image_export_config(format_name: str, quality: int) -> dict:
    """Resolve optional lightweight companion image export settings."""
    normalized_format = format_name.lower()
    if normalized_format != "webp":
        raise ValueError(f"unsupported compressed image format: {format_name}")
    if not 1 <= int(quality) <= 100:
        raise ValueError("compressed image quality must be between 1 and 100")
    return {
        "suffix": ".webp",
        "pil_format": "WEBP",
        "quality": int(quality),
        "method": 6,
    }

def parse_frontmatter(text: str) -> dict[str, str] | None:
    """Minimal YAML-frontmatter parser: returns top-level key/value strings."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    out: dict[str, str] = {}
    for line in lines[1:]:
        if line.strip() == "---":
            return out
        if ":" in line and not line.startswith((" ", "\t", "#")):
            key, _, value = line.partition(":")
            out[key.strip()] = value.strip()
    return None

def _walk_subcall_times(obj, acc: list) -> None:
    """Collect every execution_time under any rlm_calls list, whatever the shape."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == "rlm_calls" and isinstance(v, list):
                for c in v:
                    if isinstance(c, dict) and c.get("execution_time") is not None:
                        acc.append(round(float(c["execution_time"]), 3))
            else:
                _walk_subcall_times(v, acc)
    elif isinstance(obj, list):
        for v in obj:
            _walk_subcall_times(v, acc)

import hashlib


def subprocess_error_digest(*streams: str) -> str:
    """Commit to one bounded controller error code without logging its value."""

    candidates = {
        candidate
        for stream in streams
        for line in stream.splitlines()
        if line.startswith("error=")
        for candidate in (line.removeprefix("error="),)
        if 1 <= len(candidate) <= 128
        and candidate.isascii()
        and all(
            character.islower() or character.isdigit() or character == "_"
            for character in candidate
        )
    }
    selected = next(iter(candidates)) if len(candidates) == 1 else "unclassified"
    return hashlib.sha256(
        f"codexqb-controller-error-v1:{selected}".encode("ascii")
    ).hexdigest()

def _repository_object_format_from_config(data: bytes) -> str:
    """Read only the format extension needed by the private Git snapshot.

    The source config is never copied into the runtime repository.  This tiny
    parser recognizes the active ``core.repositoryFormatVersion`` and
    ``extensions.objectFormat`` assignments, rejects conflicting duplicates,
    and ignores every unrelated setting.  The synthesized runtime config below
    therefore cannot inherit repository-controlled execution behavior.
    """

    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise ValueError("git_evidence_unsafe_repository_config") from exc
    section = ""
    values: dict[tuple[str, str], str] = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith(("#", ";")):
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise ValueError("git_evidence_unsafe_repository_config")
            section_text = line[1:-1].strip()
            if not section_text:
                raise ValueError("git_evidence_unsafe_repository_config")
            section = section_text.split(None, 1)[0].casefold()
            continue
        if not section:
            raise ValueError("git_evidence_unsafe_repository_config")
        if "=" in line:
            key_text, value_text = line.split("=", 1)
            key = key_text.strip().casefold()
            value = value_text.strip().casefold()
        else:
            key = line.casefold()
            value = "true"
        if not key:
            raise ValueError("git_evidence_unsafe_repository_config")
        identity = (section, key)
        if identity not in {
            ("core", "repositoryformatversion"),
            ("extensions", "objectformat"),
        }:
            continue
        previous = values.setdefault(identity, value)
        if previous != value:
            raise ValueError("git_evidence_unsafe_repository_config")

    object_format = values.get(("extensions", "objectformat"), "sha1")
    version = values.get(("core", "repositoryformatversion"), "0")
    if object_format == "sha1" and version in {"0", "1"}:
        return "sha1"
    if object_format == "sha256" and version == "1":
        return "sha256"
    raise ValueError("git_evidence_unsupported_object_format")

def _pair_concatenation_has_record_terminator(
    text: str,
    cursor: int,
    boundary: int,
    expected_closers: tuple[str, ...] = (),
    *,
    allow_line_terminator: bool = True,
) -> str | None:
    """Return a content-free finding when a literal expression is not closed.

    ``expected_closers`` records containers opened after the pair separator.
    They are consumed inside-out before the ordinary enclosing-record
    terminator is accepted.  This keeps placeholder suppression behind the
    complete bounded expression grammar: calls, indexing, boolean operators,
    adjacent literals, comments, and other executable tails cannot be hidden
    behind an otherwise safe first fragment.
    """

    for expected in reversed(expected_closers):
        while cursor < boundary and text[cursor] in " \t":
            cursor += 1
        if cursor >= boundary:
            return (
                "secret_scan_structured_context_limit"
                if boundary < len(text)
                else "secret_scan_credential_expression_unsupported"
            )
        if text[cursor] != expected:
            return "secret_scan_credential_expression_unsupported"
        cursor += 1

    while cursor < boundary and text[cursor] in " \t":
        cursor += 1
    if cursor >= len(text):
        return None
    if cursor >= boundary:
        return (
            "secret_scan_structured_context_limit"
            if boundary < len(text)
            else None
        )
    if text[cursor] in "\r\n":
        return (
            None
            if allow_line_terminator
            else "secret_scan_credential_expression_unsupported"
        )
    if text[cursor] in ",)]};":
        return None
    return "secret_scan_credential_expression_unsupported"

def _pair_wrapper_end(text: str, cursor: int, boundary: int) -> int | None:
    """Return the end of a bounded bytes/bytearray wrapper prefix, if present."""

    lowered = text[cursor : min(boundary, cursor + 16)].lower()
    name = "bytearray" if lowered.startswith("bytearray") else "bytes" if lowered.startswith("bytes") else ""
    if not name:
        return None
    end = cursor + len(name)
    while end < boundary and text[end] in " \t":
        end += 1
    if end >= boundary or text[end] != "(":
        return None
    end += 1
    while end < boundary and text[end] in " \t":
        end += 1
    return end

def plugin_skill_contract_errors(data: bytes | None) -> list[str]:
    """Validate the canonical, invokable CodexQB skill frontmatter."""

    if data is None:
        return ["package_plugin_skills_missing"]
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return ["package_plugin_skill_frontmatter_invalid"]
    if "\x00" in text or "\r" in text or "\t" in text:
        return ["package_plugin_skill_frontmatter_invalid"]
    lines = text.split("\n")
    if len(lines) < 5 or lines[0] != "---" or lines[3] != "---":
        return ["package_plugin_skill_frontmatter_invalid"]
    errors: list[str] = []
    if lines[1] != "name: codexqb":
        errors.append("package_plugin_skill_name_invalid")
    description_prefix = "description: "
    if not lines[2].startswith(description_prefix):
        errors.append("package_plugin_skill_description_invalid")
    else:
        description = lines[2].removeprefix(description_prefix)
        if (
            not description
            or len(description) > 512
            or any(ord(character) < 32 for character in description)
        ):
            errors.append("package_plugin_skill_description_invalid")
    if not any(line.strip() for line in lines[4:]):
        errors.append("package_plugin_skill_body_missing")
    return errors

def _dynamic_suite(stem: str) -> str | None:
    """Classify bounded extension modules whose names encode their gate."""

    if stem.endswith("_platform"):
        return "platform"
    if stem.startswith("test_mount_identity") or stem.startswith("test_doctor"):
        return "unit"
    if stem.startswith("test_package_") or stem.startswith("test_artifact_package"):
        return "package"
    return None

import struct


def _zip_extra_field_errors(data: bytes) -> list[str]:
    """Validate bounded extra-field framing and identify ZIP64 records."""

    offset = 0
    while offset < len(data):
        if len(data) - offset < 4:
            return ["package_zip_envelope_invalid"]
        header_id, payload_size = struct.unpack_from("<HH", data, offset)
        offset += 4
        if payload_size > len(data) - offset:
            return ["package_zip_envelope_invalid"]
        if header_id == 0x0001:
            return ["package_zip_zip64_rejected"]
        offset += payload_size
    return []

def archive_entry_has_ancestor_conflict(
    portable: str,
    is_directory: bool,
    member_types: dict[str, bool],
    descendant_ancestors: set[str],
) -> bool:
    """Compatibility helper with depth-bounded lookups and no prior-entry scan."""

    parts = portable.split("/")
    return any(
        member_types.get("/".join(parts[:depth])) is False
        for depth in range(1, len(parts))
