def _normalize_task_key(rel_path: str) -> str:
    """Strip scenario-XX level to get canonical category/task key."""
    import re
    parts = rel_path.replace("\\", "/").split("/")
    parts = [p for p in parts if not re.match(r"^scenario-\d+$", p)]
    return "/".join(parts)

def _lcs_len(a: list[str], b: list[str]) -> int:
    """Longest common subsequence length — order-preserving match that
    tolerates absent tokens anywhere, unlike a first-miss cursor."""
    if not a or not b:
        return 0
    prev = [0] * (len(b) + 1)
    for x in a:
        cur = [0]
        for j, y in enumerate(b, 1):
            cur.append(prev[j - 1] + 1 if x == y else max(prev[j], cur[j - 1]))
        prev = cur
    return prev[-1]

def _valid_bulk_extraction(parsed) -> dict | None:
    """Strict response validation. Returns a cleaned payload or None.

    Contract: `claims` must be a list. An EMPTY list is a valid
    'read, no relevant evidence' result. A non-list, or a non-empty list
    containing zero well-formed claim objects, is a parse failure.
    """
    if not isinstance(parsed, dict) or not isinstance(parsed.get("claims"), list):
        return None
    raw = parsed["claims"]
    cleaned = [
        c for c in raw
        if isinstance(c, dict) and str(c.get("content", "")).strip()
    ]
    if raw and not cleaned:
        return None
    return {"claims": cleaned}

from typing import Any
import json
import re


def parse_json(text: str) -> Any:
    """Robustly parse JSON from model output (fences, preambles, trailing junk)."""
    if not text:
        return None
    text = text.strip()
    fence = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL)
    if fence:
        text = fence.group(1).strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass
    # First balanced object or array
    for open_ch, close_ch in (("{", "}"), ("[", "]")):
        start = text.find(open_ch)
        if start == -1:
            continue
        depth = 0
        in_str = False
        escape = False
        for i in range(start, len(text)):
            ch = text[i]
            if escape:
                escape = False
                continue
            if ch == "\\":
                escape = True
                continue
            if ch == '"':
                in_str = not in_str
                continue
            if in_str:
                continue
            if ch == open_ch:
                depth += 1
            elif ch == close_ch:
                depth -= 1
                if depth == 0:
                    try:
                        return json.loads(text[start:i + 1])
                    except json.JSONDecodeError:
                        break
    return None

def _assemble_sections(filename: str, section_outputs: list[tuple[str, list[str]]],
                       residual_note: str) -> str:
    """Deterministic assembly: code supplies headings and concatenates in plan
    order. No model call rewrites, summarizes, or drops sections."""
    is_xlsx = filename.lower().endswith(".xlsx")
    parts: list[str] = []
    if is_xlsx:
        # Sheets are the structure; injected headings would collide.
        for _title, texts in section_outputs:
            parts.extend(t for t in texts if t.strip())
        if residual_note:
            rows = "\n".join(
                f"| {line.lstrip('- ').strip()} |"
                for line in residual_note.splitlines() if line.strip()
            )
            parts.append("## Sheet: Limitations\n| Unresolved material "
                         "question |\n| --- |\n" + rows)
    else:
        for title, texts in section_outputs:
            body = "\n\n".join(t for t in texts if t.strip())
            if not body:
                body = "(no packet-supported content for this section)"
            if title:
                parts.append(f"## {title}\n\n{body}")
            else:
                parts.append(body)
        if residual_note:
            parts.append("## Limitations\n\nThe following material questions "
                         "were not fully resolved during the investigation:\n"
                         + residual_note)
    return "\n\n".join(parts)

def _dedup_claims(claims, cap: int) -> list:
    """Remove near-duplicate claims by content fingerprint, keep highest-confidence."""
    seen: set[str] = set()
    out = []
    for c in claims:
        key = c.content[:200].lower().strip()
        if key not in seen:
            seen.add(key)
            out.append(c)
        if len(out) >= cap:
            break
    return out

def _usable_repair(draft: str, repaired: str | None) -> bool:
    """Reject parse failures and obvious truncation from the repair pass."""
    if not repaired:
        return False
    cleaned = repaired.strip()
    if not cleaned:
        return False
    if len(draft) < 1200:
        return len(cleaned) >= len(draft) * 0.5
    return len(cleaned) >= max(1200, int(len(draft) * 0.6))

def _rotate(queue: list[str], iteration: int, stride: int, take: int) -> list[str]:
    """Deterministic rotation: offset advances by `stride` per iteration;
    `take` rows are returned with wraparound and no duplicates."""
    if not queue or take <= 0:
        return []
    offset = ((max(iteration, 1) - 1) * stride) % len(queue)
    rotated = queue[offset:] + queue[:offset]
    return rotated[:take]

def _generation_metadata(task_data: dict, deliverables: dict) -> dict:
    """Build metadata safe for generation — no evaluator/benchmark fields."""
    return {
        "title": task_data.get("title", ""),
        "work_type": task_data.get("work_type", ""),
        "deliverables": deliverables,
    }

def _bezier_point(t: float, p0: tuple, p1: tuple, p2: tuple) -> tuple:
    """Quadratic Bezier curve point at parameter t."""
    x = (1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t ** 2 * p2[0]
    y = (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t ** 2 * p2[1]
    return (x, y)

from typing import Any, Awaitable, Callable, Dict, List, Optional, Set, Tuple


def _detect_cloudflare(page_content: str) -> Optional[str]:
    """Detect the type of Cloudflare challenge in the page content.

    Returns: 'non-interactive', 'managed', 'interactive', 'embedded', or None.
    """
    challenge_types = ("non-interactive", "managed", "interactive")
    for ctype in challenge_types:
        if f"cType: '{ctype}'" in page_content:
            return ctype

    # Check for embedded turnstile captcha
    if 'challenges.cloudflare.com/turnstile/v' in page_content:
        return "embedded"

    return None

def _is_domain_blocked(hostname: str, blocked_domains: frozenset) -> bool:
    """Check if a hostname matches any blocked domain (including subdomains)."""
    if not hostname:
        return False
    for domain in blocked_domains:
        if hostname == domain or hostname.endswith(f".{domain}"):
            return True
    return False

def redact_key(key: str) -> str:
    """Redact a key for display. Shows first 8 + last 4 chars."""
    if len(key) <= 12:
        return key[:4] + "..." + key[-4:] if len(key) > 8 else "***"
    return key[:8] + "..." + key[-4:]

def _error_status(resp) -> int:
    """Honest status: -1 for network errors (no HTTP response), else the real
    HTTP status. Lets downstream logic distinguish 'server returned 500' from
    'connection died'."""
    if resp is None:
        return -1
    status = getattr(resp, "status", 0) or 0
    if status == 0 and getattr(resp, "error", ""):
        return -1
    return status

def page_type_from_error(error: str) -> str:
    """Map a finalized error string to a page_type override (definitive signals).

    Returns "" when the error does not imply a page_type, so the structural
    page_type from detect_page_type stands.
    """
    if not error:
        return ""
    e = error.lower()
    if e.startswith("js_shell_detected"):
        return "js_shell"
    if e.startswith("auth_required") or e.startswith("not_a_pdf") and "auth" in e:
        return "auth_wall"
    if e.startswith("geo_redirect_detected"):
        return "redirect"
    return ""

from typing import List, Optional
import re


def extract_text_content(
    page,
    css_selector: Optional[str] = None,
    main_content_only: bool = False,
) -> str:
    """Extract plain text from a page (strip all HTML tags)."""
    raw_body = getattr(page, 'body', None)
    encoding = getattr(page, 'encoding', 'utf-8') or 'utf-8'

    if raw_body:
        html = raw_body.decode(encoding, errors="replace")
    elif hasattr(page, 'content'):
        html = page.content
    else:
        return ""

    if css_selector and hasattr(page, 'css'):
        selected = page.css(css_selector)
        if selected:
            parts = []
            for el in selected:
                root = getattr(el, '_root', el)
                if hasattr(root, 'text_content'):
                    parts.append(root.text_content())
                else:
                    parts.append(str(root))
            return " ".join(p for p in parts if p)

    # Strip tags
    text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<noscript[^>]*>.*?</noscript>', '', text, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<[^>]+>', ' ', text)
    # Collapse whitespace
    text = re.sub(r'\s+', ' ', text).strip()
    return text

def _extract_encoding(content_type: str) -> str:
    """Extract charset from a content-type header."""
    if not content_type:
        return "utf-8"
    for part in content_type.split(";"):
        part = part.strip().lower()
        if part.startswith("charset="):
            return part.split("=", 1)[1].strip().strip('"').strip("'")
    return "utf-8"

def _thread_user_messages(thread: list[dict]) -> list[dict]:
    """Each conversation entry as its own user message, with a speaker label so
    the model can tell the issue, others, and its own past replies apart."""
    out = []
    for e in thread:
        if e["is_self"]:
            label = "(you said earlier)"
        elif e["author"] == "the issue":
            label = "(the issue, opening the thread)"
        elif " " in e["author"]:  # a sentinel like "the latest commenter", not a login
            label = f"({e['author']} commented)"
        else:
            label = f"(@{e['author']} commented)"
        out.append({"role": "user", "content": f"{label}\n{e['body']}".strip()})
    return out

def block_comment_anchor(block: dict, body: str) -> dict:
    """A review-comment entry anchored to a block. Multi-line blocks use
    start_line/line (GitHub spans start_line..line on the RIGHT side); single-line
    blocks omit start_line."""
    anchor = {"path": block["path"], "side": "RIGHT", "line": block["end"], "body": body}
    if block["start"] != block["end"]:
        anchor["start_line"] = block["start"]
        anchor["start_side"] = "RIGHT"
    return anchor

import re


def clean_code(raw: str) -> str:
    """Pull code out of a response that may be wrapped in ``` fences or prefaced
    with chatter. Lenient: if there's a fenced block, take it; otherwise strip any
    stray fences and return the rest."""
    t = (raw or "").strip()
    m = re.search(r"```[a-zA-Z0-9_+-]*\n(.*?)```", t, re.S)
    if m:
        t = m.group(1)
    else:
        t = re.sub(r"^```[a-zA-Z0-9_+-]*\s*", "", t)
        t = re.sub(r"```\s*$", "", t)
    return t.strip("\n")

def cookie_direction(full_diff: str) -> tuple[str, int, int]:
    """Decide MORE vs FEWER cookies straight from the diff — no model needed.
    More added lines than removed = more cookies."""
    added = removed = 0
    for line in full_diff.splitlines():
        if line.startswith("+") and not line.startswith("+++"):
            added += 1
        elif line.startswith("-") and not line.startswith("---"):
            removed += 1
    return ("MORE_COOKIES" if added >= removed else "FEWER_COOKIES"), added, removed

def action_pattern_matches(pattern: str, action_type: str) -> bool:
    """Simple glob-style matching: 'send_*' matches 'send_email'."""
    if pattern == "*":
        return True
    if pattern.endswith("*"):
        prefix = pattern[:-1]
        return action_type.lower().startswith(prefix.lower())
    return action_type.lower() == pattern.lower()

def _gate_decision_schema(allowed_actions: tuple[str, ...]) -> dict:
    """Skeleton json_schema for a gate decision; the validator still owns detail."""
    return {
        "name": "gate_decision",
        "strict": False,
        "schema": {
            "type": "object",
            "properties": {
                "action": {"type": "string", "enum": list(allowed_actions)},
                "reason": {"type": "string"},
                "params": {"type": "object"},
                "selection": {"type": "array"},
                "dedup_strategies": {"type": "object"},
                "replan_goal": {"type": "string"},
                "clarifying_question": {"type": "string"},
