def validate_tar_manifest(manifest: dict, expected_total: int | None = None) -> int:
    """Validates the internal consistency of the tar manifest
    (`bg-remover-data/tar/_manifest.json`) and returns `total_pairs`; raises a
    CLEAR RuntimeError on every inconsistency (continuing silently = the risk
    of training on missing/corrupt data):
    - `shards` must be a non-empty list, `total_pairs` a positive integer;
    - every shard entry must have `name`/`pairs`/`bytes`, with `pairs`/`bytes` > 0;
    - shard names must be unique (the same tar must not be counted twice);
    - the sum of shard `pairs` must equal `total_pairs`;
    - if `expected_total` is given, `total_pairs` must also equal it (the
      packing cell passes the source TRAIN listing length — guaranteeing the
      manifest describes the same dataset as the Drive listing)."""
    shards = manifest.get("shards")
    total = manifest.get("total_pairs")
    if not isinstance(shards, list) or not shards:
        raise RuntimeError(
            f"tar manifest has no non-empty 'shards' list (the packing cell may "
            f"never have run, or may have died halfway): {shards!r}"
        )
    if not isinstance(total, int) or total <= 0:
        raise RuntimeError(f"tar manifest has no positive 'total_pairs' field: {total!r}")
    names: list[str] = []
    total_from_shards = 0
    for entry in shards:
        name, pairs, n_bytes = entry.get("name"), entry.get("pairs"), entry.get("bytes")
        if not name or not isinstance(pairs, int) or pairs <= 0 or not isinstance(n_bytes, int) or n_bytes <= 0:
            raise RuntimeError(f"corrupt shard entry (name/pairs/bytes missing or <= 0): {entry!r}")
        names.append(name)
        total_from_shards += pairs
    if len(set(names)) != len(names):
        raise RuntimeError(f"tar manifest contains duplicate shard names: {names}")
    if total_from_shards != total:
        raise RuntimeError(
            f"sum of shard 'pairs' ({total_from_shards}) does not match the manifest's "
            f"'total_pairs' value ({total}) — manifest is corrupt, re-run the packing cell."
        )
    if expected_total is not None and total != expected_total:
        raise RuntimeError(
            f"manifest 'total_pairs' value ({total}) does not match the expected "
            f"source pair count ({expected_total})."
        )
    return total

from typing import Any, Callable
import copy
import json


def public_settings_snapshot(settings: dict[str, Any]) -> dict[str, Any]:
    """Return settings with secrets removed for tool responses."""

    snapshot = copy.deepcopy(settings)
    server = snapshot.get("local_server")
    if isinstance(server, dict) and server.get("auth_token"):
        server["auth_token"] = "***"
    api_tts = snapshot.get("api_tts")
    if isinstance(api_tts, dict):
        for provider in api_tts.values():
            if isinstance(provider, dict) and provider.get("api_key"):
                provider["api_key"] = "***"
    for custom in snapshot.get("custom_tts_engines", []) or []:
        if isinstance(custom, dict) and custom.get("api_key"):
            custom["api_key"] = "***"
    return json.loads(json.dumps(snapshot, default=str))

def detailed_pip_args(args: list[str]) -> list[str]:
    """Enable verbose package and download progress for pip install commands."""

    detailed = list(args)
    if detailed and detailed[0] == "install":
        detailed[1:1] = ["--verbose", "--progress-bar", "on"]
    return detailed

def mon_ordering_ok(ordered_node_names: list[str], mon_nodes: list[str]) -> bool:
    """True when no MON node is shut down before a node without one."""
    mons = {m for m in mon_nodes if m}
    seen_mon = False
    for name in ordered_node_names:
        if name in mons:
            seen_mon = True
        elif seen_mon:
            return False
    return True

def _legacy_host_key(host_entry: dict) -> str:
    """The pre-id key of a submitted entry: type + node name."""
    return f"{host_entry.get('type') or 'pve'}:{host_entry.get('name')}"

def _render_json(subject: str, body: str, severity: str, payload: dict) -> dict:
    """The original payload: subject, body and the complete status snapshot."""
    return {"json": {"subject": subject, "body": body, "severity": severity, "status": payload}}

def _split_line(line: str) -> list[str]:
    """Split a upsd response line into tokens, honouring "quoted values" and backslashes."""
    tokens: list[str] = []
    buf: list[str] = []
    quoted = False
    escaped = False
    started = False
    for ch in line:
        if escaped:
            buf.append(ch)
            escaped = False
            started = True
        elif ch == "\\":
            escaped = True
        elif ch == '"':
            quoted = not quoted
            started = True  # an empty "" is a real, empty token
        elif ch in " \t" and not quoted:
            if started:
                tokens.append("".join(buf))
                buf.clear()
                started = False
        else:
            buf.append(ch)
            started = True
    if started:
        tokens.append("".join(buf))
    return tokens

def _extract_returns(df, column=None, use_raw=False):
    """Extract returns series from a DataFrame.
    If use_raw or CSV has returns_lin/log → use as-is.
    Otherwise → compute pct_change from prices.
    """
    if column and column in df.columns:
        col = column
    else:
        col = df.columns[0]
    if use_raw:
        return df[col].dropna().values
    if col.startswith('return') or col in ('returns_lin', 'returns_log', 'lin_return', 'log_return'):
        return df[col].dropna().values
    return df[col].pct_change().dropna().values

def unbiased_estimator(p_hat, n):
    """Bias correction for small samples under binomial:
    p_unbiased = (successes + 1) / (n + 2).
    Use when n < 30 to avoid extreme p_hat = 0 or 1.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    successes = p_hat * n
    return (successes + 1) / (n + 2)

def _to_num(v):
    """Convierte a float si es posible."""
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)):
        return v
    try:
        return float(str(v).replace(",", "").strip())
    except (ValueError, TypeError):
        return None

def parse_symbol(sym_str: str) -> tuple[str, str]:
    """Parse 'GGAL:NASDAQ' o 'NASDAQ:GGAL' a (TICKER, EXCHANGE).

    Heuristica: el exchange es el componente que matchea una lista conocida.
    Si no se puede determinar, asume formato TICKER:EXCHANGE (lo mas comun
    en Google Finance).
    """
    if ":" not in sym_str:
        raise ValueError(f"Simbolo invalido: {sym_str!r}. Esperado TICKER:EXCHANGE (ej: GGAL:NASDAQ)")
    parts = sym_str.split(":", 1)
    a, b = parts[0].upper(), parts[1].upper()
    KNOWN_EXCHANGES = {
        "NASDAQ", "NYSE", "AMEX", "BCBA", "BYMA", "BME", "BMV", "BMFBOVESPA",
        "XETR", "FWB", "LSE", "EURONEXT", "MIL", "SIX", "TSE", "JPX", "HKEX",
        "SSE", "SZSE", "KRX", "NSE", "BSE", "ASX", "INDEXDJX", "INDEXSP",
        "INDEXNASDAQ", "INDEXRUSSELL", "INDEXCBOE", "INDEXDB", "INDEXFTSE",
        "INDEXNIKKEI", "INDEXHSI", "INDEXMADRID", "INDEXBOM",
    }
    if b in KNOWN_EXCHANGES:
        return (a, b)
    if a in KNOWN_EXCHANGES:
        return (b, a)  # flip: el usuario paso EXCHANGE:TICKER
    # Default: asumir TICKER:EXCHANGE (formato standard)
    return (a, b)

