def parse_wrbfr(text: str) -> list[tuple[str, Any]]:
    """Parse del response format wrb.fr de Google.

    Estructura:
      )]}'
      <size>
      [["wrb.fr","<rpcId>","<JSON_serialized_array>",null,null,null,"generic"], ...]
      <size>
      [...mas entries...]

    Returns:
        Lista de (rpc_id, parsed_data). data ya viene parseado con doble json.loads.
    """
    if not text.startswith(")]}'"):
        # Algunos errores no traen este prefix
        return []
    body = text[4:].strip()
    results = []
    for line in body.split("\n"):
        line = line.strip()
        if not line or line.isdigit():
            continue
        try:
            arr = json.loads(line)
        except json.JSONDecodeError:
            continue
        for item in arr:
            if (
                isinstance(item, list) and len(item) >= 3
                and item[0] == "wrb.fr"
                and isinstance(item[1], str)
                and item[2]
            ):
                rpc_id = item[1]
                try:
                    parsed = json.loads(item[2])
                except json.JSONDecodeError:
                    parsed = item[2]
                results.append((rpc_id, parsed))
    return results

from html import unescape
import re


def parse_quote(html):
    """Extrae datos de cotizacion de la pagina HTML de investing.com."""
    out = {}
    # precio
    m = re.search(r'data-test="instrument-price-last"[^>]*>([0-9.,]+)<', html)
    if m: out["last"] = m.group(1)
    # JSON embebido
    m = re.search(r'"last"\s*:\s*([\d.]+)', html)
    if m: out["last_raw"] = float(m.group(1))
    m = re.search(r'"last_close"\s*:\s*([\d.]+)', html)
    if m: out["last_close"] = float(m.group(1))
    m = re.search(r'"change"\s*:\s*"?(-?[\d.]+)"?', html)
    if m: out["change"] = float(m.group(1))
    m = re.search(r'"change_pct"\s*:\s*"?(-?[\d.]+)"?', html)
    if m: out["change_pct"] = float(m.group(1))
    m = re.search(r'"bid"\s*:\s*([\d.]+)', html)
    if m: out["bid"] = float(m.group(1))
    m = re.search(r'"ask"\s*:\s*([\d.]+)', html)
    if m: out["ask"] = float(m.group(1))
    m = re.search(r'"open"\s*:\s*([\d.]+)', html)
    if m: out["open"] = float(m.group(1))
    m = re.search(r'"high"\s*:\s*([\d.]+)', html)
    if m: out["high"] = float(m.group(1))
    m = re.search(r'"low"\s*:\s*([\d.]+)', html)
    if m: out["low"] = float(m.group(1))
    m = re.search(r'"volume"\s*:\s*"?(\d+)"?', html)
    if m: out["volume"] = int(m.group(1))
    m = re.search(r'"avg_volume"\s*:\s*"?(\d+)"?', html)
    if m: out["avg_volume"] = int(m.group(1))
    m = re.search(r'"prev_close"\s*:\s*([\d.]+)', html)
    if m: out["prev_close"] = float(m.group(1))
    m = re.search(r'"pair_id"\s*:\s*(\d+)', html)
    if m: out["pair_id"] = int(m.group(1))
    m = re.search(r'"name"\s*:\s*"([^"]+)"\s*,\s*"symbol"\s*:\s*"([^"]+)"', html)
    if m: out["name"], out["symbol"] = m.group(1), m.group(2)
    m = re.search(r'"currency"\s*:\s*"([^"]+)"', html)
    if m: out["currency"] = m.group(1)
    m = re.search(r'"exchange"\s*:\s*"([^"]+)"', html)
    if m: out["exchange"] = m.group(1)
    m = re.search(r'"country"\s*:\s*"([^"]+)"', html)
    if m: out["country"] = m.group(1)
    m = re.search(r'"updated_time"\s*:\s*"?(\d+)"?', html)
    if m: out["updated_epoch"] = int(m.group(1))
    m = re.search(r'"timezone"\s*:\s*"([^"]+)"', html)
    if m: out["timezone"] = m.group(1)
    # title
    m = re.search(r'<title>([^<]+)</title>', html)
    if m: out["page_title"] = unescape(m.group(1))
    return out

def element_box(el: dict) -> list[int] | None:
    """Where the element claims to be, in source pixels."""
    sr = el.get("source_region")
    if isinstance(sr, dict) and sr.get("w") and sr.get("h"):
        return [int(sr["x"]), int(sr["y"]), int(sr["w"]), int(sr["h"])]
    x, y = el.get("x"), el.get("y")
    w, h = el.get("w"), el.get("h")
    if x is not None and y is not None and w and h:
        return [int(x), int(y), int(w), int(h)]
    if el.get("type") == "line" and el.get("x1") is not None:
        x1, y1 = float(el["x1"]), float(el["y1"])
        x2, y2 = float(el.get("x2", x1)), float(el.get("y2", y1))
        pad = 4
        return [int(min(x1, x2) - pad), int(min(y1, y2) - pad),
                int(abs(x2 - x1) + 2 * pad), int(abs(y2 - y1) + 2 * pad)]
    if el.get("type") == "text" and x is not None and y is not None and el.get("font_size"):
        fs = float(el["font_size"])
        text = el.get("text") or ""
        return [int(x), int(y - fs), max(8, int(len(text) * fs * 0.62)), int(fs * 1.4)]
    return None

from typing import Any
import base64


def _extract_image_bytes(obj: Any) -> tuple[bytes, str] | None:
    """Best-effort extraction for Labnana/OpenAI/Gemini-like JSON responses."""
    if isinstance(obj, dict):
        inline = obj.get("inlineData") or obj.get("inline_data")
        if isinstance(inline, dict) and inline.get("data"):
            mime = inline.get("mimeType") or inline.get("mime_type") or "image/png"
            return base64.b64decode(str(inline["data"])), str(mime)
        if obj.get("b64_json"):
            return base64.b64decode(str(obj["b64_json"])), "image/png"
        if obj.get("data") and str(obj.get("mimeType") or obj.get("mime_type") or "").startswith("image/"):
            mime = obj.get("mimeType") or obj.get("mime_type") or "image/png"
            return base64.b64decode(str(obj["data"])), str(mime)
        for value in obj.values():
            found = _extract_image_bytes(value)
            if found:
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = _extract_image_bytes(value)
            if found:
                return found
    return None

def normalize_latex(latex: str) -> str:
    """Return a mathtext-ready formula body without display delimiters."""
    text = latex.strip()
    if text.startswith("$$") and text.endswith("$$"):
        text = text[2:-2].strip()
    elif text.startswith("$") and text.endswith("$"):
        text = text[1:-1].strip()
    elif text.startswith(r"\(") and text.endswith(r"\)"):
        text = text[2:-2].strip()
    elif text.startswith(r"\[") and text.endswith(r"\]"):
        text = text[2:-2].strip()
    return text

def nest(fills: list[dict]) -> None:
    """Set each fill's parent to the smallest region that fully contains it."""
    for child in fills:
        cx, cy, cw, ch = child["bbox"]
        best = None
        best_area = None
        for parent in fills:
            if parent is child:
                continue
            px, py, pw, ph = parent["bbox"]
            if px <= cx and py <= cy and px + pw >= cx + cw and py + ph >= cy + ch:
                if best_area is None or pw * ph < best_area:
                    best, best_area = parent, pw * ph
        child["parent"] = best["id"] if best else None

def _format_number(n: float) -> str:
    """Format a float for compact SVG attribute output."""
    if abs(n - round(n)) < 1e-6:
        return str(int(round(n)))
    s = f"{n:.2f}".rstrip('0').rstrip('.')
    return s or '0'

import re


def _parse_float(val: str | None, default: float = 0.0) -> float:
    """Best-effort float parse, tolerating trailing ``px`` etc."""
    if val is None or val == '':
        return default
    try:
        return float(re.sub(r'(px|pt|em|%|rem)$', '', val.strip()))
    except (ValueError, AttributeError):
        return default

def get_crop_anchor(align: str) -> tuple[float, float]:
    """
    Return the crop anchor point based on the align value.

    Returns: (x_anchor, y_anchor)
        x_anchor: 0.0 (left), 0.5 (center), 1.0 (right)
        y_anchor: 0.0 (top), 0.5 (center), 1.0 (bottom)
    """
    x_map = {'xMin': 0.0, 'xMid': 0.5, 'xMax': 1.0}
    y_map = {'YMin': 0.0, 'YMid': 0.5, 'YMax': 1.0}

    x_anchor = 0.5
    y_anchor = 0.5

    for key, val in x_map.items():
        if key in align:
            x_anchor = val
            break

    for key, val in y_map.items():
        if key in align:
            y_anchor = val
            break

    return (x_anchor, y_anchor)

def _detect_icon_style(content: str) -> str:
    """Detect whether an icon is fill-based or stroke-based."""
    # stroke="currentColor" with fill="none" → stroke style
    if 'stroke="currentColor"' in content and 'fill="none"' in content:
        return 'stroke'
    return 'fill'

