import re


def strip_nonsemantic_markdown(text: str) -> str:
    """Remove HTML comments and fenced code before checking semantic markers."""

    text = re.sub(r"<!--.*?-->", "", text, flags=re.DOTALL)
    output: list[str] = []
    fence_char: str | None = None
    fence_length = 0

    for line in text.splitlines(keepends=True):
        match = re.match(r"^\s{0,3}(`{3,}|~{3,})(.*)$", line.rstrip("\r\n"))
        if fence_char is None and match:
            marker = match.group(1)
            fence_char = marker[0]
            fence_length = len(marker)
            output.append("\n" if line.endswith("\n") else "")
            continue
        if fence_char is not None:
            closing = re.match(
                r"^\s{0,3}([`~]{3,})\s*$", line.rstrip("\r\n")
            )
            if (
                closing
                and closing.group(1)[0] == fence_char
                and len(closing.group(1)) >= fence_length
            ):
                fence_char = None
                fence_length = 0
            output.append("\n" if line.endswith("\n") else "")
        else:
            output.append(line)

    return "".join(output)

def same_work(a, b, minlen=34):
    """True if two dedup keys denote the same paper (equal or long prefix)."""
    if a == b:
        return True
    lo, hi = (a, b) if len(a) <= len(b) else (b, a)
    return len(lo) >= minlen and hi.startswith(lo)

def _infer_data_type(fact: dict) -> str:
    """Return actual/estimate/forecast; use explicit data_type when present."""
    dtype = (fact.get('data_type') or '').strip().lower()
    if dtype in ('actual', 'estimate', 'forecast'):
        return dtype
    text = ' '.join(str(fact.get(k, '')) for k in ('ctx', 'met', 'title')).lower()
    if any(k in text for k in ('预测', 'forecast', 'projected', 'projection', '预计到', '有望达到')):
        return 'forecast'
    if any(k in text for k in ('估算', '预估', '预计', 'estimate', '约', '大约', '左右')):
        return 'estimate'
    return 'actual'

def _result_text(result) -> str:
    """Pull reading-order text from RapidOCR 3 output, with a v1 list fallback."""
    txts = getattr(result, "txts", None)
    if txts:
        to_md = getattr(result, "to_markdown", None)
        if callable(to_md):
            md = to_md()
            if md and "没有检测" not in md:
                return md
        return "\n".join(t for t in txts if t and str(t).strip())
    if not result:
        return ""
    # rapidocr-onnxruntime 1.x: list of [box, text, score]
    lines = []
    for item in result:
        if len(item) > 1 and item[1]:
            lines.append(item[1])
    return "\n".join(lines)

def _pick_cleanup_model(models: list[str]) -> str:
    """Prefer a fast chat/flash model; skip dedicated reasoners for cleanup."""
    skip = ("reasoner", "o1-", "o3-", "o4-")
    scored: list[tuple[int, str]] = []
    for m in models:
        low = m.lower()
        if any(s in low for s in skip):
            continue
        score = 0
        if any(k in low for k in ("flash", "chat", "mini", "haiku", "turbo")):
            score += 2
        if "pro" in low:
            score -= 1
        scored.append((score, m))
    scored.sort(key=lambda x: -x[0])
    return scored[0][1] if scored else models[0]

def _friendly_conversion_error(exc: Exception) -> tuple[str, str]:
    """Return (detail, suggested_action) — readable, not raw exception names."""
    blob = f"{type(exc).__name__} {exc}".lower()
    if "password" in blob or "encrypted" in blob:
        return (
            "This file is password-protected.",
            "Unlock it, save an unprotected copy, then try again.",
        )
    if (
        "pdfsyntax" in blob
        or "no /root" in blob
        or "eof marker" in blob
        or "startxref" in blob
        or ("xref" in blob and "pdf" in blob)
    ):
        return (
            "This PDF is damaged or not a real PDF.",
            "Open it in a PDF reader to check, or export it again from the original app.",
        )
    if "badzipfile" in blob or "not a zip" in blob or "truncated zip" in blob:
        return (
            "This Office file is damaged or incomplete.",
            "Open it in Word, Excel, or PowerPoint, save a new copy, then try again.",
        )
    if "permission" in blob or "access is denied" in blob or "errno 13" in blob:
        return (
            "The file could not be read.",
            "Close it if it is open in another app, then try again.",
        )
    return (
        "The file could not be converted.",
        "The file may be corrupted or contain content that can't be extracted. Try another file.",
    )

import json


def _present_markdown(fmt: str, text: str) -> str:
    """JSON/XML come through as raw text — wrap them so Preview renders as a code block."""
    text = text or ""
    if not text.strip():
        return text
    if fmt == "json":
        body = text.strip()
        if body.startswith("```"):
            return text
        try:
            body = json.dumps(json.loads(body), indent=2, ensure_ascii=False)
        except (json.JSONDecodeError, ValueError, TypeError):
            pass
        return f"```json\n{body.rstrip()}\n```\n"
    if fmt == "xml":
        body = text.strip()
        if body.startswith("```"):
            return text
        # HtmlConverter may already have turned XML into Markdown.
        if body.startswith("<"):
            return f"```xml\n{body}\n```\n"
        return text
    return text

import re


def numeric_version(version: str) -> tuple[int, ...]:
    """Return a comparable numeric prefix for ordinary PEP 440 versions."""
    match = re.match(r"^(\d+(?:\.\d+)*)", version)
    if not match:
        raise ValueError(f"unsupported locked version {version!r}")
    return tuple(int(part) for part in match.group(1).split("."))

