import re


def _parse_zh_table(app_js: str) -> dict[str, str]:
    """The reviewed English→Chinese strings from app.js's ``I18N.zh`` table."""
    start = app_js.find("const I18N = {")
    if start == -1:
        raise ValueError(
            "app.js no longer defines `const I18N`; the blog chrome cannot bake its translations"
        )
    open_brace = app_js.find("{", start)
    depth = 0
    end = -1
    for index in range(open_brace, len(app_js)):
        if app_js[index] == "{":
            depth += 1
        elif app_js[index] == "}":
            depth -= 1
            if depth == 0:
                end = index
                break
    if end == -1:
        raise ValueError(
            "app.js's I18N table is unbalanced; the blog chrome cannot bake its translations"
        )
    table: dict[str, str] = {}
    # Object keys are quoted or bare JS identifiers (both appear in the table).
    pair = re.compile(r'(?:"((?:[^"\\]|\\.)*)"|([A-Za-z_$][\w$]*))\s*:\s*"((?:[^"\\]|\\.)*)"')
    for quoted, bare, value in pair.findall(app_js[open_brace:end]):
        table[quoted or bare] = value
    return table

import re


def _echoes_title(text: str, title: str) -> bool:
    """True when the card opens by repeating its own repo name and says no more."""
    slug = title.rsplit("/", 1)[-1]
    normalize = lambda value: re.sub(r"[^a-z0-9]+", "", value.lower())  # noqa: E731
    return normalize(text) == normalize(slug)

def _hex_to_ass(hex_color: str, alpha: int = 0) -> str:
    """Convert ``#RRGGBB`` to an ASS ``&HAABBGGRR`` colour string."""
    h = hex_color.lstrip("#")
    r, g, b = h[0:2], h[2:4], h[4:6]
    return f"&H{alpha:02X}{b}{g}{r}".upper()

def classify_sso_account_state(state: dict) -> str:
    """Map inspect_sso_account_state() into flagged / clean / error / unknown.

    Aligns with the live risk gate:
      - botFlagSource in (1, 2)
      - policy=deny (any event, including $registration / $login)
    """
    if not isinstance(state, dict):
        return "unknown"
    bf = state.get("bot_flag_source")
    policy = str(state.get("policy") or "").strip().lower()
    if state.get("denied") or bf in (1, 2) or policy == "deny":
        return "flagged"
    if state.get("found"):
        return "clean"
    try:
        status = int(state.get("status_code") or 0)
    except (TypeError, ValueError):
        status = 0
    if status != 200 or str(state.get("error") or "").strip():
        return "error"
    return "unknown"

def _frame_rows(frame):
    """A market-data frame as a list of row dicts, whatever shape it arrived in.

    pandas DataFrame, this bridge's serialisable marker, a list of dicts, or a
    dict of column arrays -- the same four shapes quote_utils deals with. No
    pandas import: this also runs inside QMT's embedded Python.
    """
    if frame is None:
        return []
    if isinstance(frame, dict) and frame.get("__bigqmt_type__") == "DataFrame":
        return _frame_rows(frame.get("records") or [])
    if hasattr(frame, "columns") and hasattr(frame, "iloc"):
        try:
            columns = list(frame.columns)
            return [{name: frame[name][i] for name in columns}
                    for i in range(len(frame))]
        except Exception:
            return []
    if isinstance(frame, (list, tuple)):
        return [row for row in frame if isinstance(row, dict)]
    if isinstance(frame, dict):
        columns = {k: v for k, v in frame.items() if hasattr(v, "__len__")
                   and not isinstance(v, (str, bytes))}
        if not columns:
            return [dict(frame)]
        length = min(len(v) for v in columns.values())
        return [{k: v[i] for k, v in columns.items()} for i in range(length)]
    return []

def _market_data_answer_empty(answer):
    """True when no code in the answer carries a single row.

    Covers both shapes get_market_data_ex can return: the raw path's
    serialisable marker dict (records list) and the plain path's pandas
    frames (index length). Anything unrecognised counts as an answer rather
    than as empty -- a retry must never replace data with nothing.
    """
    if not isinstance(answer, dict) or not answer:
        return True
    for value in answer.values():
        if isinstance(value, dict) and value.get("__bigqmt_type__") == "DataFrame":
            if value.get("records"):
                return False
        elif hasattr(value, "index"):
            try:
                if len(value.index) > 0:
                    return False
            except Exception:
                return False
        elif value:
            return False
    return True

def _data_attribute_names(row):
    """Public non-callable attribute names on a QMT row object.

    dir() alone lists methods too. Reading each one to check is safe -- the
    values are discarded -- but a property can raise, so each getattr is
    guarded rather than assumed.
    """
    names = []
    for name in dir(row):
        if name.startswith("_"):
            continue
        try:
            value = getattr(row, name)
        except Exception:
            continue
        if not callable(value):
            names.append(name)
    return sorted(names)

def _first_nonzero(row, names, default=0.0):
    """First candidate attribute with a non-zero numeric value."""
    for name in names:
        value = getattr(row, name, None)
        if value is None:
            continue
        try:
            number = float(value)
        except (TypeError, ValueError):
            continue
        if number:
            return number
    return default

def _drop_placeholder_rows(df):
    """Big QMT fills dates it has no local data for with all-zero rows. A real bar
    never has close/open == 0, so drop those placeholders — the cache should hold
    only real bars, not 0-fill padding."""
    for col in ("close", "open", "price", "lastPrice"):
        if col in getattr(df, "columns", []):
            try:
                # 不 reset_index：时间轴可能在索引上（MiniQMT 形态），重置会丢掉它。
                return df[df[col] != 0]
            except Exception:
                return df
    return df

def normalize_option_type(option_type):
    """Return ``C`` or ``P`` for common QMT/English/Chinese spellings."""
    text = str(option_type or "").strip().upper()
    if text in ("C", "CALL", "认购", "购"):
        return "C"
    if text in ("P", "PUT", "认沽", "沽"):
        return "P"
    raise ValueError("option_type must be C/CALL or P/PUT, got %r" % option_type)

def _latest_field_value(market_data, stock_code, field_name):
    """Return the newest raw field value from dict/list/DataFrame data."""
    if not isinstance(market_data, dict):
        return None
    frame = market_data.get(stock_code)
    if frame is None:
        frame = market_data.get(str(stock_code).upper())
    if frame is None:
        return None

    if hasattr(frame, "columns") and field_name in getattr(frame, "columns", ()):
        values = frame[field_name]
        if hasattr(values, "dropna"):
            values = values.dropna()
        try:
            return values.iloc[-1]
        except Exception:
            return None

    if isinstance(frame, dict):
        values = frame.get(field_name)
        if isinstance(values, dict):
            if not values:
                return None
            return values[sorted(values.keys())[-1]]
        if isinstance(values, (list, tuple)):
            if not values:
                return None
            if field_name in ("bidPrice", "askPrice"):
                return values[-1] if isinstance(values[-1], (list, tuple)) else values
            return values[-1]
        return values

    if isinstance(frame, (list, tuple)):
        for row in reversed(frame):
            if isinstance(row, dict) and field_name in row:
                return row.get(field_name)
    return None

def order_sys_id_of(value):
    """Best available broker string for something a caller handed back.

    Accepts an ``OrderId``, a bare string, or the int a caller round-tripped
    through JSON and lost the string half of.
    """
    carried = getattr(value, "order_sys_id", None)
    if carried:
        return str(carried)
    if value is None:
        return ""
    return str(value)

def _strip_chat_echo(text: str) -> str:
    """Drop decoded user/prompt echo and keep only the assistant's generated answer."""

    markers = (
        "<|im_start|>assistant\n",
        "\nassistant\n\n",
        "\nassistant\n",
        "assistant\n\n",
        "assistant\n",
    )
    best_index = -1
    best_marker = ""
    for marker in markers:
        index = text.rfind(marker)
        if index > best_index:
            best_index = index
            best_marker = marker
    if best_index >= 0:
        return text[best_index + len(best_marker) :].lstrip()
    return text

def build_cot_answer_prompt(base_prompt: str, reasoning: str, max_chars: int = 8000) -> str:
    """Inject the separately generated reasoning into the final code turn."""

    plan = (reasoning or "").strip()
    if not plan:
        raise ValueError("CoT reasoning stage returned no text")
    if len(plan) > max_chars:
        plan = plan[:max_chars].rstrip() + "\n...[reasoning truncated]"
    return (
        base_prompt.rstrip()
        + "\n\nA separate reasoning turn produced the following reconstruction plan:\n"
        + "<reconstruction_plan>\n"
        + plan
        + "\n</reconstruction_plan>\n\n"
        + "Follow this plan, but now return only the final executable Python script. "
        + "Do not repeat or discuss the plan.\n"
    )

