def export_cookies_from_page(page: Any) -> list[dict]:
    """Best-effort export of cookies from a DrissionPage tab/browser."""
    if page is None:
        return []
    cookies = None
    for getter in (
        lambda: page.cookies(all_domains=True, all_info=True),
        lambda: page.cookies(all_domains=True),
        lambda: page.cookies(),
    ):
        try:
            cookies = getter()
            if cookies:
                break
        except TypeError:
            continue
        except Exception:
            continue
    if not cookies:
        try:
            browser = getattr(page, "browser", None)
            if browser is not None:
                cookies = browser.cookies()
        except Exception:
            cookies = None
    if isinstance(cookies, list):
        return [c for c in cookies if isinstance(c, dict)]
    return []

def _sanitize_file_segment(value: str) -> str:
    """Mirror CPA CredentialFileName sanitize rules."""
    value = (value or "").strip()
    if not value:
        return ""
    out: list[str] = []
    for ch in value:
        if (
            ("a" <= ch <= "z")
            or ("A" <= ch <= "Z")
            or ("0" <= ch <= "9")
            or ch in {"@", ".", "_", "-"}
        ):
            out.append(ch)
        else:
            out.append("-")
    return "".join(out).strip("-")

def _wind_strength_label(code, rep: dict) -> str:
    """Human label for a /wind/strength/vs/0 code from the device's own
    modesName array (parallel-indexed with supportedModes), lowercased --
    used only for codes _DEVICE_TO_FAN doesn't already cover (issue #155:
    a board using codes "0"/"31"-"35" instead of the "0"-"4" scale
    _DEVICE_TO_FAN was built from, with modesName giving the real labels).
    Falls back to the raw code lowercased when modesName is absent or
    misaligned."""
    supported = rep.get("x.com.samsung.da.supportedModes") or []
    names = rep.get("x.com.samsung.da.modesName") or []
    if code in supported and len(names) == len(supported):
        return str(names[supported.index(code)]).lower()
    return str(code).lower()

