def command_digest(command: str) -> str:
    """A sha256 digest of the command — the ledger's identity for the check
    without ever storing the command text itself."""

    return "sha256:" + hashlib.sha256((command or "").encode("utf-8", "replace")).hexdigest()

def _agent_id_from_child_session(client_session_id: str) -> tuple[str, str] | None:
    """``<parent>:agent-<hex>`` → ``(parent, "agent-<hex>")``; else ``None``."""

    if not isinstance(client_session_id, str) or ":" not in client_session_id:
        return None
    parent, _, agent = client_session_id.partition(":")
    if not parent or not agent.startswith("agent-"):
        return None
    return parent, agent

import hashlib


def verifier_bundle_checksum_bytes(verifier: bytes, support: bytes) -> str:
    """Return the domain-separated digest for executable verifier sources."""

    digest = hashlib.sha256()
    for filename, source in (
        ("verifier.py", verifier),
        ("verifier_support.py", support),
    ):
        digest.update(filename.encode("utf-8"))
        digest.update(b"\0")
        digest.update(source)
        digest.update(b"\0")
    return digest.hexdigest()

