def pcm16_from_wav(wav_bytes: bytes) -> tuple[bytes, int, int]:
    """Strip the WAV container, returning (pcm16_bytes, sample_rate, sample_count).
    Walks chunks so non-standard headers still parse."""
    if wav_bytes[:4] != b"RIFF" or wav_bytes[8:12] != b"WAVE":
        raise ValueError("not a RIFF/WAVE file")
    pos = 12
    sample_rate = 24000
    pcm = b""
    while pos + 8 <= len(wav_bytes):
        chunk_id = wav_bytes[pos:pos + 4]
        chunk_size = int.from_bytes(wav_bytes[pos + 4:pos + 8], "little")
        if chunk_id == b"fmt " and pos + 16 <= len(wav_bytes):
            sample_rate = int.from_bytes(wav_bytes[pos + 12:pos + 16], "little")
        elif chunk_id == b"data":
            pcm = wav_bytes[pos + 8:pos + 8 + chunk_size]
            break
        pos += 8 + chunk_size
        if chunk_size % 2 == 1:
            pos += 1
    if not pcm:
        raise ValueError("WAV has no data chunk")
    return pcm, sample_rate, len(pcm) // 2

def _register_state(regs: dict) -> dict:
    """Normalize one CPU's register snapshot for exact comparison.

    Everything the debug server reports is kept, with the register array
    rendered as fixed-width hex so a textual diff of two captures points at
    the register that actually differs.
    """
    state: dict[str, object] = {}
    for key, value in regs.items():
        if key == "r" and isinstance(value, list):
            state["r"] = [f"0x{int(item):08x}" for item in value]
        elif isinstance(value, int):
            state[key] = f"0x{int(value):08x}"
        else:
            state[key] = value
    return state

import base64


def expand_roots(record):
    """Yield (addr, hits) from a schema-4 root bitmap record.

    Hit counts are stored per 256-byte block rather than per address, so a
    block's count is split evenly across the addresses set inside it; summing a
    whole block reproduces its count exactly.
    """
    base = int(record["addr"], 16)
    blocks = record.get("root_hits") or []
    found = []
    for key, stride in (("root_arm", 4), ("root_thumb", 2)):
        blob = record.get(key)
        if not blob:
            continue
        for index, byte in enumerate(base64.b64decode(blob)):
            if not byte:
                continue
            for bit in range(8):
                if byte & (1 << bit):
                    found.append(base + (index * 8 + bit) * stride)
    n = len(blocks)
    if not n:
        return [(addr, 0) for addr in found]

    def block_of(addr):
        return min(((addr - base) * n) // 4096, n - 1)

    counts = {}
    for addr in found:
        counts[block_of(addr)] = counts.get(block_of(addr), 0) + 1
    return [(addr, blocks[block_of(addr)] // counts[block_of(addr)])
            for addr in found]

def phase_emu_ms(report: dict) -> dict[str, float]:
    """Emulation ms per frame for each phase of a single-repetition report."""
    runs = [r for r in report.get("runs", []) if r.get("valid")]
    if not runs:
        raise SystemExit("report contains no valid repetition")
    out: dict[str, float] = {}
    for phase in runs[0].get("phases", []):
        label = phase.get("label")
        value = (phase.get("phase_ms_per_frame") or {}).get("emu")
        if label and value is not None:
            out[label] = float(value)
    return out

def _limpar_latin1(texto):
    """Fontes core do fpdf2 são latin-1: remove o que não codifica (emoji etc.)."""
    return (texto or "").encode("latin-1", "replace").decode("latin-1")

def _e_erro_de_cota(erro):
    """Detecta erro de cota/rate-limit olhando primeiro os atributos estruturados
    da exceção (status_code/code do SDK) e o nome da classe, e só por último o
    texto da mensagem - o texto muda entre versões de SDK e idiomas, os códigos não."""
    status = getattr(erro, "status_code", None) or getattr(erro, "code", None)
    if status == 429:
        return True
    if type(erro).__name__ in ("RateLimitError", "ResourceExhausted", "TooManyRequests"):
        return True
    texto = str(erro).lower()
    return (
        "quota" in texto
        or "resource_exhausted" in texto
        or "429" in texto
        or "rate limit" in texto
    )

def montar_mensagem_conclusao(contagens):
    """Mensagem final com o funil completo: quantas empresas foram capturadas,
    quantas viraram leads e POR QUE as demais ficaram de fora. Sem essa
    transparência o usuário compara com o que vê no Google ("lá tem 20, aqui
    puxou 2") e conclui que a busca está bugada."""
    total = contagens["total_no_csv"]
    novos = contagens["novos"]

    descartes = []
    if contagens.get("descartados_por_site_ok"):
        descartes.append(f"{contagens['descartados_por_site_ok']} já têm site bom (não precisam de você)")
    if contagens.get("descartados_nota_baixa"):
        descartes.append(f"{contagens['descartados_nota_baixa']} com nota baixa ou sem avaliações")
    if contagens.get("descartados_sem_telefone"):
        descartes.append(f"{contagens['descartados_sem_telefone']} sem telefone pra contato")

    ja_conhecidos = total - novos - sum((
        contagens.get("descartados_por_site_ok", 0),
        contagens.get("descartados_nota_baixa", 0),
        contagens.get("descartados_sem_telefone", 0),
        contagens.get("erros_de_linha", 0),
    ))
    if ja_conhecidos > 0:
        descartes.append(f"{ja_conhecidos} já estavam na sua base (dados atualizados)")

    detalhe_funil = f" Das {total} empresas capturadas: " + "; ".join(descartes) + "." if descartes else ""

    if novos == 0:
        return "Busca concluída: nenhum lead novo desta vez." + detalhe_funil
    return (
        f"Busca concluída: {novos} lead(s) novo(s) - "
        f"{contagens['novos_sem_site']} sem site e {contagens['novos_site_ruim']} com site ruim!"
        + detalhe_funil
    )

def traduzir_erro_scraper(stderr, returncode):
    """Converte a saída crua do scraper (ou timeout) numa mensagem que o usuário leigo entende."""
    texto = (stderr or "").lower()

    if "could not install driver" in texto or "playwright" in texto:
        # o caso mais comum NÃO é falta de Node: é um google-maps-scraper.exe
        # antigo tentando baixar uma versão do driver do Playwright que a
        # Microsoft já removeu dos servidores (o download volta 404)
        return (
            "O scraper não conseguiu preparar o navegador interno. Causa mais comum: "
            "seu google-maps-scraper.exe está desatualizado e procura um componente "
            "(driver do Playwright) que a Microsoft já tirou do ar. Baixe a versão mais "
            "recente em github.com/gosom/google-maps-scraper/releases e substitua o .exe "
            "na pasta backend/. Se persistir, confira se o Node.js está instalado. "
            "Alternativa sem scraper: use a Google Places API em Configurações → Fonte de dados."
        )
    if "no such file" in texto or "not found" in texto:
        return "O programa google-maps-scraper.exe não foi encontrado na pasta do projeto."
    if "deadline exceeded" in texto or "timeout" in texto:
        return "A busca no Google Maps demorou demais e foi interrompida. Tente de novo."

    return (
        f"A busca falhou (código {returncode}). Veja os detalhes completos em logs/prospeccao.log."
    )

def zoom_para_raio(raio_m):
    """Nível de zoom do Google Maps compatível com o raio escolhido: raio maior
    exige zoom menor pra área caber na janela de busca. 1km→15, 5km→13, 50km→9."""
    import math
    return max(8, min(17, round(15 - math.log2(max(raio_m, 500) / 1000))))

def _contar_por_nicho_tabela(conexao, tabela):
    """Total de leads e taxa de conversão (fechou/total) por nicho (já separado da
    cidade), considerando só leads ativos (não ignorados). Ordenado por total desc."""
    linhas = conexao.execute(
        f"""
        SELECT
            nicho,
            COUNT(*) AS total,
            SUM(CASE WHEN status = 'fechou' THEN 1 ELSE 0 END) AS fechados
        FROM {tabela}
        WHERE status != 'ignorado' AND nicho IS NOT NULL AND nicho != ''
        GROUP BY nicho
        ORDER BY total DESC
        """
    ).fetchall()

    nichos = {}
    for linha in linhas:
        nichos[linha["nicho"]] = {
            "total": linha["total"],
            "fechados": linha["fechados"] or 0,
        }
    return nichos

