def generate_recommendations(checks: list[dict[str, Any]]) -> list[str]:
    """Generate human-readable recommendations based on audit results."""
    recommendations: list[str] = []
    for check in checks:
        if check["count"] > 0:
            if check["check"] == "missing_sources":
                recommendations.append(
                    f"Add source references to {check['count']} finding entries lacking citations."
                )
            elif check["check"] == "conflicting_data":
                recommendations.append(
                    f"Resolve {check['count']} conflicting data points by verifying with additional sources."
                )
            elif check["check"] == "coverage_gaps":
                recommendations.append(
                    f"Fill {check['count']} required field gaps with additional research."
                )
            elif check["check"] == "source_duplicates":
                recommendations.append(
                    f"Review {check['count']} sources referenced by multiple tasks for potential redundancy."
                )
    if not recommendations:
        recommendations.append("No issues found. Research integrity looks good.")
    return recommendations

from typing import Any


def calculate_overall_coverage(matrix: dict[str, Any]) -> float:
    """Return the ratio of covered item-field cells."""
    total = 0
    covered = 0
    for field_map in matrix.values():
        for cell in field_map.values():
            total += 1
            if cell["covered"]:
                covered += 1
    return covered / total if total > 0 else 1.0

def next_id(prefix: str, existing_ids: list[str]) -> str:
    """Generate the next sequential id for a given prefix, avoiding gaps and duplicates."""
    numbers: list[int] = []
    for id_str in existing_ids:
        if id_str.startswith(f"{prefix}-"):
            try:
                numbers.append(int(id_str.split("-", 1)[1]))
            except ValueError:
                pass
    next_num = max(numbers, default=0) + 1
    return f"{prefix}-{next_num}"

def check_expanded_aggregate_layout(surface, label: str, failures: list[str]) -> None:
    """Confirm that opening report controls cannot stack aggregate tiles."""
    details = surface.locator("#options")
    details.evaluate("element => { element.open = true; }")
    surface.wait_for_timeout(100)
    layout = surface.evaluate(
        """() => {
          const grid = document.querySelector("#aggregate-grid");
          const gridBox = grid.getBoundingClientRect();
          const boxes = [...grid.querySelectorAll(".aggregate-tile")].map(tile => {
            const box = tile.getBoundingClientRect();
            return {left: box.left, top: box.top, right: box.right, bottom: box.bottom};
          });
          const overlaps = [];
          for (let first = 0; first < boxes.length; first += 1) {
            for (let second = first + 1; second < boxes.length; second += 1) {
              const a = boxes[first];
              const b = boxes[second];
              const overlapX = Math.min(a.right, b.right) - Math.max(a.left, b.left);
              const overlapY = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
              if (overlapX > 1 && overlapY > 1) overlaps.push([first, second]);
            }
          }
          const outside = boxes
            .map((box, index) => ({box, index}))
            .filter(({box}) =>
              box.left < gridBox.left - 1 || box.top < gridBox.top - 1 ||
              box.right > gridBox.right + 1 || box.bottom > gridBox.bottom + 1
            )
            .map(({index}) => index);
          return {overlaps, outside};
        }"""
    )
    details.evaluate("element => { element.open = false; }")
    if layout["overlaps"]:
        failures.append(
            f"{label}: expanded controls overlap aggregate tiles {layout['overlaps']}"
        )
    if layout["outside"]:
        failures.append(
            f"{label}: expanded controls push aggregate tiles outside their grid "
            f"{layout['outside']}"
        )

def check_wide_command_layout(page, label: str, failures: list[str]) -> None:
    """Confirm command guides use their available desktop content width."""
    metrics = page.evaluate(
        """() => {
          const content = document.querySelector(".md-typeset");
          const selectors = {
            paragraph: ".md-typeset > p",
            list: ".md-typeset > ul, .md-typeset > ol",
            command: ".md-typeset .highlight",
            table: ".md-typeset .md-typeset__table"
          };
          const contentWidth = content?.getBoundingClientRect().width || 0;
          const widths = {};
          for (const [name, selector] of Object.entries(selectors)) {
            const element = document.querySelector(selector);
            widths[name] = element?.getBoundingClientRect().width || null;
          }
          return {contentWidth, widths};
        }"""
    )
    content_width = metrics["contentWidth"]
    if not content_width:
        failures.append(f"{label}: command-guide content width is unavailable")
        return
    for name, width in metrics["widths"].items():
        if width is not None and width < content_width * 0.9:
            failures.append(
                f"{label}: {name} uses only {width:.0f}px of "
                f"{content_width:.0f}px available content width"
            )

def _sample_worker_plan(n_items, cores, requested=None):
	"""Return (sample_workers, cores_per_sample) for multi-sample dispatch."""
	if n_items <= 1:
		return 1, cores
	if requested is not None:
		workers = max(1, min(int(requested), n_items))
	else:
		if cores is None:
			return 1, cores
		workers = min(n_items, max(1, int(cores) // 8))
	cores_per_sample = cores
	if cores is not None and workers > 1:
		cores_per_sample = max(1, int(cores) // workers)
	return workers, cores_per_sample

import html


def consensus_logo_svg(consensus: str, height: int = 42) -> str:
    """Render a compact inline SVG consensus logo for HTML reports."""

    consensus = "".join(base for base in str(consensus).upper() if base in "ACGTN")
    if not consensus:
        return ""
    colors = {"A": "#2f9e44", "C": "#1971c2", "G": "#f08c00", "T": "#d6336c", "N": "#868e96"}
    width_per_base = 18
    width = max(width_per_base, len(consensus) * width_per_base)
    labels = []
    for idx, base in enumerate(consensus):
        x = idx * width_per_base + width_per_base / 2
        labels.append(
            f'<text x="{x:.1f}" y="{height - 10}" text-anchor="middle" '
            f'font-family="Arial, sans-serif" font-weight="700" font-size="22" '
            f'fill="{colors.get(base, colors["N"])}">{html.escape(base)}</text>'
        )
    return (
        f'<svg class="motif-logo" width="{width}" height="{height}" '
        f'viewBox="0 0 {width} {height}" role="img" aria-label="{html.escape(consensus)}">'
        f'<rect width="{width}" height="{height}" fill="#ffffff" />'
        f'{"".join(labels)}</svg>'
    )

def build_condition_groups(signal_labels, cond_names=None):
    """Return ordered condition labels and condition-to-sample mapping."""

    if cond_names is None:
        cond_names = list(signal_labels)
    if len(cond_names) != len(signal_labels):
        raise ValueError("--cond-names must have the same length as --signals")
    groups = {}
    for signal_name, cond in zip(signal_labels, cond_names):
        groups.setdefault(cond, []).append(signal_name)
    return list(groups.keys()), groups

import re


def parse_grid_spec(grid_spec):
    """Parse a grid spec like '2x5' into integer rows/cols."""
    if grid_spec is None:
        return None
    match = re.fullmatch(r"\s*(\d+)\s*[xX]\s*(\d+)\s*", grid_spec)
    if match is None:
        raise ValueError("Grid must be formatted as <rows>x<cols>, e.g. 2x5.")
    rows, cols = int(match.group(1)), int(match.group(2))
    if rows < 1 or cols < 1:
        raise ValueError("Grid rows and columns must both be >= 1.")
    return rows, cols

def gc_fraction(sequence: str) -> float:
    """Return GC fraction over non-N bases."""

    sequence = sequence.upper()
    informative = [base for base in sequence if base in {"A", "C", "G", "T"}]
    if not informative:
        return 0.0
    return float(sum(base in {"G", "C"} for base in informative) / len(informative))

def _clamp_rekey(v) -> int:
    """0 disables proactive rekey; otherwise clamp to 1..1440 minutes."""
    try:
        m = int(v)
    except (TypeError, ValueError):
        return 30
    if m <= 0:
        return 0
    return max(1, min(1440, m))

def _iface_is_lan_candidate(name: str) -> bool:
    """True when an interface is likely a host LAN NIC, not a VPN/container tunnel."""
    n = (name or "").lower()
    if not n or n == "lo":
        return False
    skip_prefixes = (
        "docker", "br-", "veth", "virbr", "cni", "flannel", "tun", "tap",
        "wg", "ipsec", "vti", "gre", "gretap", "erspan", "sit", "nlmon",
        "uk-", "nordlynx", "tailscale", "zerotier", "zt", "ppp",
    )
    return not any(n.startswith(prefix) or n == prefix.rstrip("-")
                   for prefix in skip_prefixes)

def merge_external_sip_accounts(new_list, old_list) -> list:
    """Preserve an external SIP secret when a save omits or blanks its password."""
    old_by_username = {}
    for account in old_list or []:
        if not isinstance(account, dict):
            continue
        username = str(account.get("username") or "").strip()
        if username:
            old_by_username[username] = account

    merged = []
    for account in new_list or []:
        if not isinstance(account, dict):
            continue
        username = str(account.get("username") or "").strip()
        if not username:
            continue
        if "password" in account and str(account.get("password") or "").strip():
            password = str(account.get("password"))
        else:
            password = str((old_by_username.get(username) or {}).get("password") or "")
        if not password:
            raise ValueError(
                f"SIP account '{username}' needs a password "
                "(third-party SIP clients will get Unauthorized without one)."
            )
        merged.append({**account, "username": username, "password": password})
    return merged

def normalize_advertise_address(value) -> str:
    """Strip and lightly validate an advertise host. Empty means automatic detection."""
    value = ("" if value is None else str(value)).strip()
    if not value:
        return ""
    if any(ch.isspace() for ch in value) or "://" in value:
        raise ValueError(
            "advertise_address must be a bare IP address or hostname "
            "(for example 192.168.6.239), not a URL"
        )
    return value

def normalize_pani_node_id(m) -> str:
    """WLAN BSSID / AP MAC for i-wlan-node-id: strip : - . spaces, lower-case hex, 12 digits."""
    s = "".join(ch for ch in str(m or "") if ch.isalnum()).lower()
    if len(s) == 12 and all(ch in "0123456789abcdef" for ch in s):
        return s
    return ""

import base64


def _b64decode(payload: str) -> str:
    """Decode base64 that may be url-safe and/or missing its padding."""
    payload = payload.strip()
    payload += "=" * (-len(payload) % 4)
    return base64.urlsafe_b64decode(payload.encode()).decode("utf-8", "replace")

def _split_host_port(hostport: str) -> tuple[str, str]:
    """Split ``host:port``, tolerating bracketed IPv6 and a missing port."""
    if hostport.startswith("["):
        host, _, rest = hostport.partition("]")
        return host[1:], rest.lstrip(":")
    host, sep, port = hostport.rpartition(":")
    if not sep:
        return port, ""  # no colon at all -> the whole thing was the host
    return host, port

def _get(data, path):
    """Dotted-path lookup. Returns (found: bool, value)."""
    cur = data
    for part in (path or "").split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return False, None
    return True, cur

def _all_run_seconds(entries):
    """total_seconds for full-run ('all') entries, in order — the only comparable runs."""
    out = []
    for e in entries:
        if e.get("trigger") == "all":
            secs = (e.get("metrics") or {}).get("total_seconds")
            if isinstance(secs, (int, float)):
                out.append(secs)
