import math


def recompute(op, items, stated):
    """Recompute an aggregate over `items` and compare to `stated`.
    Returns (ok: bool, derived, reason: str). count uses exact equality;
    sum/mean/min/max use math.isclose."""
    if op == "count":
        derived = len(items)
        try:
            ok = derived == int(stated)
        except (TypeError, ValueError):
            ok = False
        return (ok, derived, "count")
    nums = []
    for x in items:
        try:
            nums.append(float(x))
        except (TypeError, ValueError):
            return (False, None, f"non-numeric item: {x!r}")
    if not nums:
        return (False, None, "no items")
    if op == "sum":
        derived = math.fsum(nums)
    elif op == "mean":
        derived = math.fsum(nums) / len(nums)
    elif op == "min":
        derived = min(nums)
    elif op == "max":
        derived = max(nums)
    else:
        return (False, None, f"unknown op: {op}")
    try:
        ok = math.isclose(derived, float(stated), rel_tol=1e-9, abs_tol=1e-12)
    except (TypeError, ValueError):
        ok = False
    return (ok, derived, op)

def decide(require_ack, latest_run_id, review_exists, acked, stop_active, retry_count, max_retries):
    """Pure policy. Returns (block: bool, reason: str, next_count: int)."""
    if not require_ack:
        return (False, "ack gate not enabled (opt-in)", 0)
    if not latest_run_id:
        return (False, "no DRAFT run to review", 0)
    if review_exists and acked:
        return (False, f"run {latest_run_id} reviewed and acknowledged", 0)
    if stop_active and retry_count >= max_retries:
        return (False, f"ack gate: retry cap ({max_retries}) reached — handing to human", retry_count)
    missing = "has no Second Opinion review" if not review_exists else "review is not acknowledged by a human"
    reason = (f"DRAFT run {latest_run_id} {missing}. Run `/second-opinion <run_dir>` then "
              f"`python3 -m secondop.ack` (a human action) before stopping.")
    return (True, reason, retry_count + 1)

def per_item_stale_rate(rows: list[dict], key: str, value: str) -> dict[str, float]:
    """Raw stale rate per item within one arm or state."""
    counts: dict[str, list[int]] = {}
    for row in rows:
        if row.get(key) != value:
            continue
        item = counts.setdefault(row["item"], [0, 0])
        item[1] += 1
        if row["grade"] == "stale":
            item[0] += 1
    return {item: stale / total for item, (stale, total) in counts.items() if total}

def _raw_grade_rate(trials: list[dict], arm: str, grade_name: str) -> float:
    """Raw (unconditional) rate of one grade over all trials in an arm."""
    arm_trials = [t for t in trials if t["arm"] == arm]
    if not arm_trials:
        return 0.0
    return sum(t["grade"] == grade_name for t in arm_trials) / len(arm_trials)

def per_item_rates(trials: list[dict], arm: str) -> dict[str, dict]:
    """Per-item stale/fresh/neither counts and conditional rate, for one arm.

    Conditional rate is stale/(stale+fresh), §3.2's primary metric, defined
    over *committed* answers only, so a `neither`-heavy arm cannot manufacture
    a low rate by simply not answering. `None` when no answer was committed;
    callers apply the §3.2 imputation rule, this function reports raw fact.
    """
    counts: dict[str, dict] = {}
    for t in trials:
        if t["arm"] != arm:
            continue
        cell = counts.setdefault(t["item"], {"stale": 0, "fresh": 0, "neither": 0})
        cell[t["grade"]] += 1
    for cell in counts.values():
        denom = cell["stale"] + cell["fresh"]
        cell["conditional_rate"] = cell["stale"] / denom if denom else None
    return counts

def rule_merge_no_files(event: dict, skip_globs: list[str]) -> bool:
    """Merge commit with no files touched."""
    if event["source"] != "git":
        return False
    return len(event.get("files", [])) == 0

def rule_session_command_noise(event: dict, skip_globs: list[str]) -> bool:
    """Session event that is just a slash command or too short with no outcome."""
    if event["source"] != "session":
        return False
    user = event.get("user", "").strip()

    # Bare slash command (no space or just "/" alone)
    if user == "/" or (user.startswith("/") and " " not in user):
        return True

    # Local command output (starts with "<")
    if user.startswith("<"):
        return True

    # Too short after strip (< 20 chars) AND no useful outcome
    if len(user) < 20 and not event.get("outcome"):
        return True

    return False

from typing import Any, Dict, List, Optional, Tuple


def _audio_file_extension(mime_type: Optional[str]) -> str:
    """Derive a file extension from a MIME type, falling back to '.bin'."""
    if not mime_type:
        return ".bin"
    # "audio/webm" -> ".webm", "audio/ogg" -> ".ogg", etc.
    ext = mime_type.split("/")[-1].split("+")[0]
    if ext:
        return f".{ext}"
    return ".bin"

from typing import AsyncGenerator, Dict, List, Optional


def _merge_tool_call_delta(pending: Dict[int, dict], delta: dict) -> None:
    """Accumulate a streamed tool-call delta into the per-index accumulator.

    Tool calls arrive in fragments: the first chunk carries id/type/name,
    later chunks append to function.arguments (and occasionally name).
    Backends that re-send the full name in later deltas are handled by
    resyncing to the latest copy rather than concatenating it.
    """
    index = delta.get("index", 0)
    entry = pending.setdefault(
        index, {"type": "function", "function": {"name": "", "arguments": ""}}
    )
    if delta.get("id"):
        entry["id"] = delta["id"]
    if delta.get("type"):
        entry["type"] = delta["type"]
    fn = delta.get("function") or {}
    if fn.get("name"):
        current_name = entry["function"]["name"]
        if current_name and current_name in fn["name"]:
            # The incoming name CONTAINS what we already have — this is the
            # signature of a backend re-sending the name (in full) in a later
            # delta; concatenating would yield "get_timeget_time". The check
            # is directional on purpose: a genuine name fragment is almost
            # never a superstring of the accumulated name, so normal
            # fragment streaming is unaffected.
            entry["function"]["name"] = fn["name"]
        else:
            entry["function"]["name"] = current_name + fn["name"]
    if fn.get("arguments"):
        entry["function"]["arguments"] += fn["arguments"]

from typing import List, Optional


def _extract_result_text(result: dict) -> str:
    """Flatten a tools/call result into the string fed back to the LLM.

    Only text blocks are usable by the LLM. Non-text blocks (base64
    images, audio, ...) are described rather than dumped: serializing
    them into the conversation is how models get shot.
    """
    parts: List[str] = []
    non_text_blocks = 0
    for block in result.get("content", []):
        if isinstance(block, dict) and block.get("type") == "text":
            parts.append(block.get("text", ""))
        elif isinstance(block, str):
            parts.append(block)
        else:
            non_text_blocks += 1
    if parts:
        return "\n".join(parts)
    if non_text_blocks:
        return f"(tool returned {non_text_blocks} non-text content block(s); no text output)"
    return "(no output)"

def _is_response(payload: dict) -> bool:
    """A JSON-RPC response has an "id" and either "result" or "error"."""
    return "id" in payload and ("result" in payload or "error" in payload)

