def _validation_error_class(error: str) -> str:
    """Stable categories for prose errors whose exact wording may improve."""

    lowered = error.lower()
    if "missing required heading" in lowered:
        return "missing_heading"
    if "unknown source" in lowered:
        return "unknown_citation"
    if "missing from references" in lowered:
        return "missing_reference"
    if "uncited source" in lowered:
        return "uncited_reference"
    if "exactly once" in lowered:
        return "duplicate_reference"
    if "validated url or doi" in lowered:
        return "reference_locator"
    if "citation" in lowered or "source id" in lowered:
        return "citation_policy"
    if "patent" in lowered or "freedom to operate" in lowered:
        return "patent_framing"
    return "other"

from typing import Any


def flatten_meta(meta: dict[str, Any]) -> dict[str, Any]:
    """Flatten one persisted result; this is the CSV/client boundary."""

    metrics = meta.get("report_metrics") or {}
    grounding = metrics.get("grounding") or {}
    usage = meta.get("usage") or {}
    report_guardrail = meta.get("report_guardrail") or {}
    row = {
        key: meta.get(key, "")
        for key in (
            "experiment_id", "block_id", "schedule_index", "position", "num",
            "rep", "topic", "variant", "nodes", "status", "fixture_digest",
            "fixture_age_days", "elapsed_seconds",
        )
    }
    row.update({
        "total_tokens": usage.get("total_tokens", ""),
        "total_requests": usage.get("total_requests", ""),
        "cost_usd": usage.get("cost_usd", ""),
        "cost_complete": usage.get("cost_complete", ""),
        "contract_status": metrics.get("contract_status", ""),
        "validation_error_count": len(metrics.get("validation_errors") or []),
        "grounding_status": grounding.get("status", ""),
        "checked_claim_lines": grounding.get("checked_claim_lines", ""),
        "unsupported_claim_lines": grounding.get("unsupported_claim_lines", ""),
        "unverifiable_claim_lines": grounding.get("unverifiable_claim_lines", ""),
        "report_guardrail_calls": report_guardrail.get("calls", ""),
        "report_guardrail_failures": report_guardrail.get("failures", ""),
        "report_guardrail_retries": report_guardrail.get("retries", ""),
        "word_count": metrics.get("word_count", ""),
        "unique_citations": metrics.get("unique_citations", ""),
        "citation_domains": ",".join(metrics.get("citation_domains") or []),
        "reviewer_corrections": meta.get("reviewer_corrections", ""),
        "draft_retention_ratio": meta.get("draft_retention_ratio", ""),
    })
    return row

def reviewer_correction_count(report: str) -> int | None:
    """Accepted exact replacements, or None when no reviewer existed."""

    marker = "## Reviewer Notes"
    if marker not in report:
        return None
    notes = report.split(marker, maxsplit=1)[1]
    if "No corrections required." in notes:
        return 0
    return sum(1 for line in notes.splitlines() if line.strip().startswith("- "))

def _role_description(group_id: str, phrases: tuple[str, ...]) -> str:
    """Project a frozen text vocabulary without consulting human labels."""

    concept = group_id.replace("_", " ")
    examples = ", ".join(phrases)
    return (
        f"Evidence that the source directly addresses {concept}; the frozen "
        f"source-text vocabulary includes: {examples}."
    )

def _agreger(data, prefixe):
    """Somme par fournisseur sur toutes les dates commencant par prefixe (jour ou mois)."""
    total = {}
    for jour, parj in data.items():
        if not str(jour).startswith(prefixe):
            continue
        for fourn, v in parj.items():
            t = total.setdefault(fourn, {"modele": v.get("modele", ""), "appels": 0,
                                         "tin": 0, "tout": 0, "cout": 0.0})
            t["appels"] += v.get("appels", 0)
            t["tin"] += v.get("tin", 0)
            t["tout"] += v.get("tout", 0)
            t["cout"] = round(t["cout"] + v.get("cout", 0.0), 4)
    return total

def _parser_index(texte: str) -> list:
    """Entrees de index.md : ### titre / - lien / - auteur / - themes / - contenu."""
    entrees, cur = [], None
    for ligne in texte.splitlines():
        if ligne.startswith("### "):
            if cur:
                entrees.append(cur)
            cur = {"titre": ligne[4:].strip(), "lien": "", "auteur": "",
                   "themes": [], "contenu": ""}
        elif cur is not None:
            s = ligne.strip()
            if s.startswith("- lien :"):
                cur["lien"] = s[len("- lien :"):].strip()
            elif s.startswith("- auteur :"):
                cur["auteur"] = s[len("- auteur :"):].strip()
            elif s.startswith("- th") and ":" in s:      # thèmes / themes
                cur["themes"] = [t.strip() for t in s.split(":", 1)[1].split(",") if t.strip()]
            elif s.startswith("- contenu :"):
                cur["contenu"] = s[len("- contenu :"):].strip()
    if cur:
        entrees.append(cur)
    return entrees

import re


def _themes_existants(index_texte: str, limite: int = 60) -> list:
    """Vocabulaire de themes deja utilise (pour eviter la proliferation)."""
    cpt = {}
    for m in re.finditer(r"^- th[eè]mes\s*:\s*(.+)$", index_texte, re.M | re.I):
        for t in m.group(1).split(","):
            t = t.strip()
            if t:
                cpt[t] = cpt.get(t, 0) + 1
    return [t for t, _ in sorted(cpt.items(), key=lambda kv: -kv[1])[:limite]]

def texte_pour_systeme(memoire):
    """Resume la memoire pour l'injecter dans la consigne systeme."""
    parties = []
    if memoire.get("preferences"):
        parties.append("Preferences : " + " ; ".join(
            f"{k} = {v}" for k, v in memoire["preferences"].items()))
    if memoire.get("people"):
        parties.append("Personnes : " + " ; ".join(
            f"{k} = {v}" for k, v in memoire["people"].items()))
    if memoire.get("projects"):
        parties.append("Projets : " + " ; ".join(
            f"{k} = {v}" for k, v in memoire["projects"].items()))
    if memoire.get("facts"):
        parties.append("Faits : " + " ; ".join(memoire["facts"]))
    if not parties:
        return ""
    return ("\n\nCe que tu sais deja sur l'utilisateur "
            "(ne le recite pas spontanement, sers-t'en) :\n" + "\n".join(parties))

def _local_seulement(request):
    """True si la requete vient VRAIMENT du poste local (pas du LAN ni du tunnel).

    On se base sur l'IP REELLE de la socket (request.client.host), non falsifiable
    par un en-tete, PLUS l'absence d'en-tetes X-Forwarded-* (que ngrok ajoute
    toujours -> identifie le trafic tunnelise). L'ancien check sur l'en-tete Host
    etait contournable (`curl -H "Host: localhost"`)."""
    if request.headers.get("x-forwarded-for") or request.headers.get("x-forwarded-host"):
        return False
    hote = (getattr(request.client, "host", "") or "").strip().lower()
    return hote in {"127.0.0.1", "::1", "localhost"}

