def _normaliser(numero):
    """Numero -> format E.164 (+33...). Accepte '06 12 ...', '0033...', '+33...'."""
    n = "".join(c for c in (numero or "") if c.isdigit() or c == "+")
    if n.startswith("+"):
        return n
    if n.startswith("00"):
        return "+" + n[2:]
    if n.startswith("0"):
        return "+33" + n[1:]
    return "+" + n if n else n

def _dropped_count(state):
    """Sessions evicted by the cap while still unsynced. Never silently reset:
    a lossily-typed but recoverable value (an int-valued string or float, from a
    hand edit or a foreign JSON writer) is coerced back, not zeroed — zeroing hid
    exactly the drops this counter exists to report, and the next mutation then
    persisted the zero. Only unrecoverable garbage falls back to 0."""
    value = state.get("dropped_unsynced_sessions")
    if isinstance(value, bool):
        return 0
    # Floats past 2**53 are no longer exact integers (1e308 "is_integer()" but
    # round-trips to a 309-digit approximation) — recoverable means EXACT.
    if isinstance(value, float) and value.is_integer() and 0 <= value <= 2 ** 53:
        value = int(value)
    elif isinstance(value, str):
        try:
            value = int(value.strip())
        except ValueError:
            return 0
    if not isinstance(value, int) or value < 0:
        return 0
    return value

from typing import Any, Mapping, Sequence


def _a22_stat_labels(value: Any) -> Any:
    """Relabel reused numeric bootstrap machinery without A9 evidence semantics."""

    if isinstance(value, dict):
        renamed = {"a9_mean": "a22_mean", "a9_ratio": "a22_ratio"}
        return {
            renamed.get(str(key), str(key)): _a22_stat_labels(item)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [_a22_stat_labels(item) for item in value]
    if isinstance(value, str):
        if value == "A9_minus_A8":
            return "A22_minus_A8"
        if value.startswith("multitown-a9-"):
            return "multitown-a22-" + value.removeprefix("multitown-a9-")
    return value

import math


def wilson_interval(successes: int, count: int, z: float = 1.959963984540054) -> tuple[float | None, float | None]:
    """Return a 95% Wilson score interval for a binomial proportion."""
    if count <= 0:
        return None, None
    proportion = successes / count
    denominator = 1 + z * z / count
    centre = (proportion + z * z / (2 * count)) / denominator
    radius = z * math.sqrt(proportion * (1 - proportion) / count + z * z / (4 * count * count)) / denominator
    return max(0.0, centre - radius), min(1.0, centre + radius)

