from typing import Any, Iterable
import hashlib


def stable_fit_dev_split(
    records: Iterable[dict[str, Any]], *, dev_per_axis: int = 10, seed: int = 20260810
) -> tuple[list[str], list[str]]:
    """Hash-rank each axis so the 250-row train subset becomes 200 fit/50 dev."""

    grouped: dict[str, list[str]] = defaultdict(list)
    for record in records:
        grouped[str(record["axis"])].append(str(record["sample_id"]))
    fit: list[str] = []
    dev: list[str] = []
    for axis in sorted(grouped):
        ranked = sorted(
            grouped[axis],
            key=lambda sample_id: hashlib.sha256(
                f"{seed}:{axis}:{sample_id}".encode("utf-8")
            ).hexdigest(),
        )
        if len(ranked) <= dev_per_axis:
            raise ValueError(f"axis {axis!r} has only {len(ranked)} records")
        dev.extend(ranked[:dev_per_axis])
        fit.extend(ranked[dev_per_axis:])
    return sorted(fit), sorted(dev)

def integrate_power(
    samples: list[dict[str, float]], start_s: float, end_s: float, baseline_w: float,
) -> dict[str, float]:
    """Piecewise-constant integration over a clipped time interval."""
    if end_s <= start_s:
        raise ValueError("end_s must be after start_s")
    ordered = sorted(samples, key=lambda item: item["time_s"])
    if not ordered:
        raise ValueError("power samples cannot be empty")
    total_j = 0.0
    incremental_j = 0.0
    for index, sample in enumerate(ordered):
        left = max(start_s, sample["time_s"])
        next_time = ordered[index + 1]["time_s"] if index + 1 < len(ordered) else end_s
        right = min(end_s, next_time)
        if right <= left:
            continue
        duration = right - left
        power = float(sample["power_w"])
        total_j += power * duration
        incremental_j += max(0.0, power - baseline_w) * duration
    return {"total_j": total_j, "incremental_j": incremental_j}

import json


def strict_json_compliant(text: str, allowed_actions: tuple[str, ...]) -> bool:
    """Check the prompt contract without the benchmark's recovery parser."""
    try:
        payload = json.loads(text.strip())
    except (json.JSONDecodeError, TypeError):
        return False
    if not isinstance(payload, dict) or payload.get("action") not in allowed_actions:
        return False
    try:
        confidence = float(payload["confidence"])
    except (KeyError, TypeError, ValueError):
        return False
    return 0.0 <= confidence <= 1.0 and isinstance(payload.get("brief_reason"), str)

def _reset_agent_context(agent) -> None:
    """Start a clean conversation context before creating or opening a project."""
    if agent and agent.is_running:
        raise RuntimeError("当前任务仍在运行，请停止或等待完成后再切换项目")
    if not agent:
        return
    agent.history = []
    agent.handler = None
    clients = getattr(agent, "llmclients", None) or [getattr(agent, "llmclient", None)]
    for client in clients:
        if client is None:
            continue
        try:
            client.backend.history = []
        except Exception:
            pass
        try:
            client.last_tools = ""
        except Exception:
            pass

