def _summary_only_pending_action(content):
    """Detect progress-only replies that promise more work but forgot tool calls."""
    if not content:
        return ""
    m = re.search(r"<summary>(.*?)</summary>", content, re.DOTALL | re.IGNORECASE)
    if not m:
        return ""
    residual = re.sub(r"<thinking>[\s\S]*?</thinking>", "", content, flags=re.IGNORECASE)
    residual = re.sub(r"<summary>[\s\S]*?</summary>", "", residual, flags=re.IGNORECASE)
    if len(re.sub(r"\s+", "", residual)) > 20:
        return ""
    summary = m.group(1).strip()
    if not summary:
        return ""
    pending_re = r"(继续|接着|随后|下一步|将|准备|开始|轮询|查询|提交|生成|审查|复审|下载|合成|拼接|开拍|执行)"
    done_re = r"(已完成全部|任务完成|全部完成|最终交付|无需继续|等待用户|需要用户|请用户|已交付)"
    if re.search(pending_re, summary) and not re.search(done_re, summary):
        return summary
    return ""

def _stamp_oai_cache_markers(messages, model):
    """Add cache_control to last 2 user messages for Anthropic models via OAI-compatible relay."""
    ml = model.lower()
    if not any(k in ml for k in ('claude', 'anthropic')): return
    user_idxs = [i for i, m in enumerate(messages) if m.get('role') == 'user']
    for idx in user_idxs[-2:]:
        c = messages[idx].get('content')
        if isinstance(c, str):
            messages[idx] = {**messages[idx], 'content': [{'type': 'text', 'text': c, 'cache_control': {'type': 'ephemeral'}}]}
        elif isinstance(c, list) and c:
            c = list(c); c[-1] = dict(c[-1], cache_control={'type': 'ephemeral'})
            messages[idx] = {**messages[idx], 'content': c}

def openai_tools_to_claude(tools):
    """[{type:'function', function:{name,description,parameters}}] → [{name,description,input_schema}]."""
    result = []
    for t in tools:
        if 'input_schema' in t: result.append(t); continue  # 已是claude格式
        fn = t.get('function', t)
        result.append({'name': fn['name'], 'description': fn.get('description', ''),
            'input_schema': fn.get('parameters', {'type': 'object', 'properties': {}})})
    return result

def _merge_history_blocks(all_blocks):
    """Merge sliding-window history blocks into one deduplicated list."""
    if not all_blocks: return []
    acc = list(all_blocks[0])
    for block in all_blocks[1:]:
        if not block: continue
        if not acc:
            acc = list(block); continue
        best = 0
        for k in range(1, min(len(acc), len(block)) + 1):
            if acc[-k:] == block[:k]: best = k
        if best > 0:
            acc.extend(block[best:])
        elif block[0] in acc:
            idx = len(acc) - 1 - acc[::-1].index(block[0])
            match_len = 0
            for j in range(min(len(block), len(acc) - idx)):
                if acc[idx + j] == block[j]: match_len = j + 1
                else: break
            acc.extend(block[match_len:])
        else:
            acc.extend(block)
    return acc

