def _normalize_identifier(identifier: str, id_type: str) -> str:
    """Remove accepted DOI/PMID wrappers before strict source lookups."""
    value = identifier.strip()
    if id_type == "doi":
        value = re.sub(
            r"^https?://(?:dx\.)?doi\.org/",
            "",
            value,
            flags=re.IGNORECASE,
        )
        return re.sub(r"^doi:\s*", "", value, flags=re.IGNORECASE)
    if id_type == "pmid":
