def _thread_ids(result):
    """Loaded thread ids from thread/loaded/list, whatever the exact shape."""
    if isinstance(result, dict):
        for key in ("data", "threadIds", "threads"):
            if key in result:
                result = result[key]
                break
    ids = []
    if isinstance(result, list):
        for item in result:
            if isinstance(item, str):
                ids.append(item)
            elif isinstance(item, dict) and item.get("id"):
                ids.append(item["id"])
    return ids

def _extract_review_decision(data: object) -> str | None:
    """Defensively pull the decision text out of the review service response.

    Returns None when the response shape doesn't match the OpenAI chat-completion
    contract (e.g. {"error": ...} with no choices). The caller treats None as
    "undecided" and applies the configured fail-open policy.
    """
    if not isinstance(data, dict):
        return None
    choices = data.get("choices")
    if not isinstance(choices, list) or not choices:
        return None
    first = choices[0]
    if not isinstance(first, dict):
        return None
    message = first.get("message")
    if not isinstance(message, dict):
        return None
    content = message.get("content")
    if content is None:
        return None
    return str(content).strip().lower()

def request_shape(*values: object) -> dict[str, int]:
    """Return a safe structural summary without logging prompts or image bytes."""
    stats = {
        "response_message_items": 0,
        "input_image_parts": 0,
        "image_url_parts": 0,
        "image_parts": 0,
        "data_url_images": 0,
        "remote_image_urls": 0,
        "literal_image_placeholders": 0,
    }

    def walk(value: object, key: str = "") -> None:
        if isinstance(value, str):
            text = value.strip()
            lower = text.lower()
            if "<image>" in lower:
                stats["literal_image_placeholders"] += 1
            if lower.startswith("data:image/"):
                stats["data_url_images"] += 1
            elif key in {"image_url", "url"} and lower.startswith(("http://", "https://")):
                stats["remote_image_urls"] += 1
            return
        if isinstance(value, list):
            for item in value:
                walk(item, key)
            return
        if not isinstance(value, dict):
            return
        item_type = str(value.get("type") or "").strip()
        if item_type == "message":
            stats["response_message_items"] += 1
        elif item_type == "input_image":
            stats["input_image_parts"] += 1
        elif item_type == "image_url":
            stats["image_url_parts"] += 1
        elif item_type == "image":
            stats["image_parts"] += 1
        for child_key, child in value.items():
            walk(child, str(child_key))

    for value in values:
        walk(value)
    return {key: value for key, value in stats.items() if value}

def _unwrap_envelope(payload: object) -> object:
    """Peel sub2api's `{code, message, data}` envelope, returning the inner `data` field
    when present. Also handles unwrapped responses from older/alt versions."""
    if isinstance(payload, dict) and "data" in payload and "code" in payload:
        return payload.get("data")
    return payload

from collections import Counter, defaultdict
from typing import Any


def compact_report(report: dict[str, Any]) -> dict[str, Any]:
    """Keep decision-relevant evidence while omitting large deterministic inventories."""
    inventory = report.get("inventory", {})
    built_in = inventory.get("built_in_doctor")
    compact_built_in: Any = built_in
    if isinstance(built_in, dict) and isinstance(built_in.get("checks"), dict):
        check_counts: Counter[str] = Counter()
        checks: dict[str, Any] = {}
        for check_id, check in built_in["checks"].items():
            if not isinstance(check, dict):
                continue
            status = str(check.get("status", "unknown"))
            check_counts[status] += 1
            checks[check_id] = {
                "status": status,
                "summary": check.get("summary"),
            }
        compact_built_in = {
            "schemaVersion": built_in.get("schemaVersion"),
            "codexVersion": built_in.get("codexVersion"),
            "overallStatus": built_in.get("overallStatus"),
            "checkStatusCounts": dict(sorted(check_counts.items())),
            "checks": checks,
        }

    skills = inventory.get("skills", {})
    compact_skills: Any = skills
    if isinstance(skills, dict):
        items = skills.get("items", [])
        compact_skills = {
            "count": skills.get("count"),
            "roots": skills.get("roots", []),
            "itemsOmitted": len(items) if isinstance(items, list) else 0,
        }

    compact_inventory = {
        "built_in_doctor": compact_built_in,
        "instructions": inventory.get("instructions"),
        "skills": compact_skills,
        "config": inventory.get("config"),
        "mcp": inventory.get("mcp"),
        "plugins": inventory.get("plugins"),
        "hooks": inventory.get("hooks"),
        "git": inventory.get("git"),
    }
    return {**report, "inventory": compact_inventory}

from typing import Any


def hook_shape_errors(hooks: Any) -> list[dict[str, str]]:
    """Validate the documented three-level event/group/handler structure."""
    if not isinstance(hooks, dict):
        return [{"path": "hooks", "error": "expected object"}]
    root_hooks = hooks.get("hooks", hooks)
    if not isinstance(root_hooks, dict):
        return [{"path": "hooks", "error": "expected event object"}]
    errors: list[dict[str, str]] = []
    for event, groups in root_hooks.items():
        if event in {"managed_dir", "windows_managed_dir"}:
            continue
        if not isinstance(groups, list):
            errors.append({"path": f"hooks.{event}", "error": "expected matcher-group list"})
            continue
        for group_index, group in enumerate(groups):
            group_path = f"hooks.{event}[{group_index}]"
            if not isinstance(group, dict):
                errors.append({"path": group_path, "error": "expected matcher-group object"})
                continue
            handlers = group.get("hooks")
            if not isinstance(handlers, list):
                errors.append({"path": f"{group_path}.hooks", "error": "expected handler list"})
                continue
            for handler_index, handler in enumerate(handlers):
                handler_path = f"{group_path}.hooks[{handler_index}]"
                if not isinstance(handler, dict):
                    errors.append({"path": handler_path, "error": "expected handler object"})
                    continue
                if handler.get("type") == "command" and not isinstance(handler.get("command"), str):
                    errors.append({"path": f"{handler_path}.command", "error": "expected command string"})
    return errors

from typing import Any
import re


def parse_provider_counts(value: Any) -> dict[str, int]:
    """Parse the redacted provider inventory emitted by `codex doctor --json`."""
    raw_items: list[tuple[Any, Any]] = []
    if isinstance(value, dict):
        raw_items = list(value.items())
    elif isinstance(value, str):
        for part in value.split(","):
            match = re.fullmatch(r"\s*([^=,]+?)\s*=\s*(\d+)\s*", part)
            if match:
                raw_items.append((match.group(1), match.group(2)))

    counts: dict[str, int] = {}
    for raw_provider, raw_count in raw_items:
        provider = str(raw_provider).strip()
        if not provider:
            continue
        try:
            count = int(raw_count)
        except (TypeError, ValueError):
            continue
        if count < 0:
            continue
        counts[provider] = counts.get(provider, 0) + count
    return counts

from typing import Any


def supported_thinking(entry: dict[str, Any], surface: str) -> set[str]:
    """Return the declared reasoning levels for one model/surface combination."""
    surface_map = entry.get("surface_thinking")
    if isinstance(surface_map, dict):
        surface_levels = surface_map.get(surface)
        if isinstance(surface_levels, list):
            return {item for item in surface_levels if isinstance(item, str)}
        return set()

    fallback = entry.get("thinking")
    if not isinstance(fallback, list):
        return set()
    return {item for item in fallback if isinstance(item, str)}

from typing import Any, Iterable


def find_exact_model_metadata(
    payload: Any, model_id: str, id_fields: tuple[str, ...]
) -> dict[str, Any] | None:
    """Find exact route metadata without fuzzy matching model names."""
    if isinstance(payload, dict):
        if any(payload.get(field) == model_id for field in id_fields):
            return payload
        for key, value in payload.items():
            if key == model_id and isinstance(value, dict):
                return value
            match = find_exact_model_metadata(value, model_id, id_fields)
            if match is not None:
                return match
    elif isinstance(payload, list):
        for value in payload:
            match = find_exact_model_metadata(value, model_id, id_fields)
            if match is not None:
                return match
    return None

def inverse_condition_target(current, goal, remaining, source):
    """Build either an inference waypoint or a raw terminal-goal condition."""
    if source == "waypoint":
        return current + (goal - current) / float(remaining)
    if source == "goal":
        return goal
    raise ValueError(f"Unknown inverse condition source: {source}")

def _trajectory_index_source(dataset):
    """Find the dataset that owns clip starts and episode offsets."""
    if hasattr(dataset, "clip_indices") and hasattr(dataset, "offsets"):
        return dataset
    for child in getattr(dataset, "datasets", []):
        try:
            return _trajectory_index_source(child)
        except ValueError:
            continue
    child = getattr(dataset, "dataset", None)
    if child is not None:
        return _trajectory_index_source(child)
    raise ValueError("Dataset does not expose clip_indices and episode offsets")

def remove_scope_plan(transformer):
    """Detach the attention scopes, restoring dense attention."""
    for index_block, block in enumerate(transformer.transformer_blocks):
        if hasattr(block.attn.processor, "alphas"):
            del block.attn.processor.alphas
        if hasattr(block.attn.processor, "betas"):
            del block.attn.processor.betas

    for index_block, block in enumerate(transformer.single_transformer_blocks):
        if hasattr(block.attn.processor, "alphas"):
            del block.attn.processor.alphas
        if hasattr(block.attn.processor, "betas"):
            del block.attn.processor.betas

def set_spa_filter(transformer, double_ids=None, single_ids=None):
    """Restrict SPA to a subset of blocks; ``None`` allows every block."""
    double = list(transformer.transformer_blocks)
    single = list(transformer.single_transformer_blocks)
    for idx, block in enumerate(double):
        block.attn.processor.spa_allowed = double_ids is None or idx in double_ids
    for idx, block in enumerate(single):
        block.attn.processor.spa_allowed = single_ids is None or idx in single_ids
